function nCr(x: number, y: number): number {
  const f = Array(x + 1).fill(0);
  f[0] = 1;
  for (let i = 1; i <= x; i++) {
    f[i] = (f[i - 1] * i) % mod;
  }
  const inv = pow(mod - 2, mod - 2, mod);
  return (f[x] * ((f[y] * f[x - y]) % mod)) % mod;
}

function inv(x: number): number {
  return pow(x, mod - 2, mod);
}

function sumx(x: number): number {
  return Math.floor((x ** 2 + x) / 2);
}

function pow(base: number, exp: number, mod: number): number {
  let result = 1;
  base = base % mod;
  while (exp > 0) {
    if (exp % 2 === 1) {
      result = (result * base) % mod;
    }
    exp = Math.floor(exp / 2);
    base = (base * base) % mod;
  }
  return result;
}

