class FastIO {
    private buffer: Buffer;
    private pos: number;
    private length: number;

    constructor(file: NodeJS.ReadableStream) {
        this.buffer = Buffer.alloc(8192);
        this.pos = 0;
        this.length = 0;
        file.on('data', (chunk: Buffer) => {
            chunk.copy(this.buffer, this.length);
            this.length += chunk.length;
        });
    }

    private read(): string {
        let result = '';
        while (this.pos < this.length) {
            if (this.buffer[this.pos] === 10) { // newline
                break;
            }
            result += String.fromCharCode(this.buffer[this.pos]);
            this.pos++;
        }
        this.pos++;
        return result.trimEnd();
    }

    public readline(): string {
        let line = '';
        while (true) {
            const chunk = this.read();
            if (chunk === '') {
                break;
            }
            line += chunk;
        }
        return line;
    }
}

