function solve(): void {
    const [n, k, x] = input().split(' ').map(Number);
    let s = input();

    if (!s.includes('*')) {
        console.log(s);
        return;
    }

    const stars = s.split('a').filter(star => star.length > 0);

    // A string of q stars can expand to 0, 1, 2, ..., q * k b's, which is
    // 1 + k * q possibilities
    const expand = stars.map(star => 1 + k * star.length);

    // Cumulative product of number of stars
    let prods: number[] = [expand[expand.length - 1]];
    for (let i = 1; i < expand.length; i++) {
        prods.push(prods[prods.length - 1] * expand[expand.length - i - 1]);
    }

    x -= 1;

    // Count how many b's to replace each * by
    let counts: number[] = [];
    for (let prod of prods.reverse()) {
        counts.push(Math.floor(x / prod));
        x -= prod * Math.floor(x / prod);
    }
    counts.push(x % prods[0]);

    // Construct the string
    let answer = '';
    let i = 1;
    let j = 0;
    while (j < s.length) {
        if (s[j] === 'a') {
            answer += 'a';
            j++;
        } else {
            answer += 'b'.repeat(counts[i]);
            i++;
            while (j < s.length && s[j] === '*') {
                j++;
            }
        }
    }

    console.log(answer);
}

