function process(A: number[], B: number[], Q: [number, number][]): number[] {
    const S: number[] = [0];
    const n = A.length;
    for (let i = 0; i < n; i++) {
        const ai = A[i];
        const bi = B[i];
        const di = bi - ai;
        S.push(S[S.length - 1] + di);
    }
    const n2 = S.length;
    const p = Math.ceil(Math.log2(n2));
    const p2 = 2 ** p;
    const minTree: number[] = new Array(2 * p2 - 1).fill(null);
    const maxTree: number[] = new Array(2 * p2 - 1).fill(null);
    for (let i = 0; i < p2; i++) {
        if (i < n) {
            minTree[i] = S[i];
            maxTree[i] = S[i];
        } else {
            minTree[i] = Infinity;
            maxTree[i] = -Infinity;
        }
    }
    for (let i = p2; i < 2 * p2 - 1; i++) {
        const i1 = (2 * p2 - 2) - i;
        const j1 = 2 * i1 + 1;
        const j2 = 2 * i1 + 2;
        const iLeft = (2 * p2 - 2) - j1;
        const iRight = (2 * p2 - 2) - j2;
        minTree[i] = Math.min(minTree[iLeft], minTree[iRight]);
        maxTree[i] = Math.max(maxTree[iLeft], maxTree[iRight]);
    }
    function findMax(l: number, r: number, startL = 0, startR = p2 - 1, startI = 2 * p2 - 2): number {
        if (startI < 0) return -Infinity;
        if (l === r) return maxTree[l];
        if (l === startL && r === startR) return maxTree[startI];
        const i1 = (2 * p2 - 2) - startI;
        const iLeft = (2 * p2 - 2) - (2 * i1 + 2);
        const iRight = (2 * p2 - 2) - (2 * i1 + 1);
        const m1 = Math.floor((startL + startR) / 2);
        if (l > m1) return findMax(l, r, startL = m1 + 1, startR = startR, startI = iRight);
        else if (r <= m1) return findMax(l, r, startL = startL, startR = m1, startI = iLeft);
        else {
            const max1 = findMax(l, m1, startL = startL, startR = m1, startI = iLeft);
            const max2 = findMax(m1 + 1, r, startL = m1 + 1, startR = startR, startI = iRight);
            return Math.max(max1, max2);
        }
    }
    function findMin(l: number, r: number, startL = 0, startR = p2 - 1, startI = 2 * p2 - 2): number {
        if (startL > l || r > startR) return Infinity;
        if (startI < 0) return Infinity;
        if (l === r) return minTree[l];
        if (l === startL && r === startR) return minTree[startI];
        const i1 = (2 * p2 - 2) - startI;
        const iLeft = (2 * p2 - 2) - (2 * i1 + 2);
        const iRight = (2 * p2 - 2) - (2 * i1 + 1);
        const m1 = Math.floor((startL + startR) / 2);
        if (l > m1) return findMin(l, r, startL = m1 + 1, startR = startR, startI = iRight);
        else if (r <= m1) return findMin(l, r, startL = startL, startR = m1, startI = iLeft);
        else {
            const min1 = findMin(l, m1, startL = startL, startR = m1, startI = iLeft);
            const min2 = findMin(m1 + 1, r, startL = m1 + 1, startR = startR, startI = iRight);
            return Math.min(min1, min2);
        }
    }
    const answer: number[] = [];
    for (const [l, r] of Q) {
        const s1 = S[l - 1];
        const s2 = S[r];
        if (s1 !== s2) {
            answer.push(-1);
        } else {
            const myMin = findMin(l, r);
            const myMax = findMax(l, r);
            if (myMin - s1 < 0) {
                answer.push(-1);
            } else {
                answer.push(myMax - s1);
            }
        }
    }
    return answer;
}

