class Dsu {
    parent: number[];

    constructor(n: number) {
        this.parent = new Array(n + 1).fill(0);
    }

    makeSet(): void {
        for (let i = 1; i <= this.parent.length - 1; i++) {
            this.parent[i] = i;
        }
    }

    findParent(node: number): number {
        if (node === this.parent[node]) {
            return node;
        }

        this.parent[node] = this.findParent(this.parent[node]);
        return this.parent[node];
    }

    union(u: number, v: number): number {
        const u_parent = this.findParent(u);
        const v_parent = this.findParent(v);

        if (u_parent !== v_parent) {
            this.parent[v_parent] = u_parent;
            return -1;
        } else {
            return 0;
        }
    }

    checkComponent(u: number, v: number): void {
        if (this.findParent(u) !== this.findParent(v)) {
            console.log('Both belongs to different components');
        } else {
            console.log('same component');
        }
    }

    reUnion(u: number, v: number): void {}
}

