import { stdin, stdout } from 'process';

const BUFSIZE = 8192;

class FastIO {
    private buffer: Buffer;
    private writable: boolean;
    private write: (s: string) => void | null;
    private newlines: number;

    constructor() {
        this.buffer = Buffer.alloc(BUFSIZE);
        this.writable = true; // Assuming stdin is always writable
        this.write = stdout.write.bind(stdout);
        this.newlines = 0;
    }

    read(): string {
        let ptr = 0, len = 0;
        while (true) {
            const b = stdin.read(BUFSIZE);
            if (!b) break;
            this.buffer.copy(b, len, 0, b.length);
            len += b.length;
        }
        return this.buffer.toString('utf-8', 0, len).trim();
    }

    readline(): string {
        let line = '';
        while (this.newlines === 0) {
            const b = stdin.read(BUFSIZE);
            if (!b) break;
            const lines = b.toString('utf-8').split('\n');
            this.buffer.copy(b, 0, lines[lines.length - 1].length + 1, b.length);
            line += lines.slice(0, -1).join('\n');
            this.newlines = lines.length - 1;
        }
        this.newlines -= 1;
        return line.trim();
    }

    flush(): void {
        if (this.writable) {
            stdout.write(this.buffer.toString('utf-8'));
            this.buffer.fill(0);
        }
    }
}

