const BUFSIZE = 8192

type FastIO struct {
	buffer   *bufio.Reader
	newlines int
}

func NewFastIO(file *os.File) *FastIO {
	return &FastIO{
		buffer: bufio.NewReaderSize(file, BUFSIZE),
	}
}

func (f *FastIO) Read() string {
	line, _ := f.buffer.ReadString('\n')
	return line
}

func (f *FastIO) ReadLine() string {
	for f.newlines == 0 {
		line, err := f.buffer.ReadString('\n')
		if err != nil {
			break
		}
		f.newlines = len(line)
	}
	f.newlines--
	return line
}

func (f *FastIO) Flush() {
	fmt.Println()
}

