func solve() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	input := scanner.Text()
	parts := strings.Split(input, " ")
	n, _ := strconv.Atoi(parts[0])
	k, _ := strconv.Atoi(parts[1])
	x, _ := strconv.Atoi(parts[2])
	s := scanner.Text()

	if !strings.Contains(s, "*") {
		fmt.Println(s)
		return
	}

	stars := strings.FieldsFunc(s, func(r rune) bool { return r != 'a' })
	expand := make([]int, len(stars))
	for i, star := range stars {
		expand[i] = 1 + k*len(star)
	}

	prods := make([]int, len(expand))
	prods[len(prods)-1] = expand[len(expand)-1]
	for i := len(prods) - 2; i >= 0; i-- {
		prods[i] = prods[i+1] * expand[i+1]
	}

	x--

	counts := make([]int, len(stars)+1)
	for i := range counts {
		if i == len(counts)-1 {
			counts[i] = x % prods[0]
		} else {
			counts[i] = x / prods[i+1]
			x -= prods[i+1] * counts[i]
		}
	}

	var answer strings.Builder
	i, j := 1, 0
	for j < len(s) {
		if s[j] == 'a' {
			answer.WriteRune('a')
			j++
		} else {
			answer.WriteString(strings.Repeat("b", counts[i]))
			i++
			for j < len(s) && s[j] == '*' {
				j++
			}
		}
	}

	fmt.Println(answer.String())
}

