	"fmt"
	"math"
	"os"
)

func process(A []int, B []int, Q [][]int) []int {
	S := make([]int, 1)
	n := len(A)
	for i := 0; i < n; i++ {
		ai := A[i]
		bi := B[i]
		di := bi - ai
		S = append(S, S[len(S)-1]+di)
	}
	n = len(S)
	p := int(math.Ceil(math.Log2(float64(n))))
	p = 1 << p
	minTree := make([]int, 2*p-1)
	maxTree := make([]int, 2*p-1)
	for i := 0; i < p; i++ {
		if i < n {
			minTree[i] = S[i]
			maxTree[i] = S[i]
		} else {
			minTree[i] = math.MaxInt32
			maxTree[i] = -math.MaxInt32
		}
	}
	for i := p; i < 2*p-1; i++ {
		i1 := (2 * p) - 2 - i
		j1 := 2 * i1 + 1
		j2 := 2 * i1 + 2
		iLeft := (2 * p) - 2 - j1
		iRight := (2 * p) - 2 - j2
		minTree[i] = min(minTree[iLeft], minTree[iRight])
		maxTree[i] = max(maxTree[iLeft], maxTree[iRight])
	}
	findMax := func(l, r, startL, startR, startI int) int {
		if startI < 0 {
			return -1
		}
		if l == r {
			return maxTree[l]
		}
		if l == startL && r == startR {
			return maxTree[startI]
		}
		i1 := (2 * p) - 2 - startI
		iLeft := (2 * p) - 2 - (2*i1 + 2)
		iRight := (2 * p) - 2 - (2*i1 + 1)
		m1 := (startL + startR) / 2
		if l > m1 {
			return findMax(l, r, m1+1, startR, iRight)
		} else if r <= m1 {
			return findMax(l, r, startL, m1, iLeft)
		} else {
			max1 := findMax(l, m1, startL, m1, iLeft)
			max2 := findMax(m1+1, r, m1+1, startR, iRight)
			return max(max1, max2)
		}
	}
	findMin := func(l, r, startL, startR, startI int) int {
		if startI < 0 {
			return -1
		}
		if l == r {
			return minTree[l]
		}
		if l == startL && r == startR {
			return minTree[startI]
		}
		i1 := (2 * p) - 2 - startI
		iLeft := (2 * p) - 2 - (2*i1 + 2)
		iRight := (2 * p) - 2 - (2*i1 + 1)
		m1 := (startL + startR) / 2
		if l > m1 {
			return findMin(l, r, m1+1, startR, iRight)
		} else if r <= m1 {
			return findMin(l, r, startL, m1, iLeft)
		} else {
			min1 := findMin(l, m1, startL, m1, iLeft)
			min2 := findMin(m1+1, r, m1+1, startR, iRight)
			return min(min1, min2)
		}
	}
	answer := make([]int, 0)
	for _, qr := range Q {
		l := qr[0] - 1
		r := qr[1]
		s1 := S[l]
		s2 := S[r]
		if s1 != s2 {
			answer = append(answer, -1)
		} else {
			myMin := findMin(l, r, 0, p-1, 2*p-2)
			myMax := findMax(l, r, 0, p-1, 2*p-2)
			if myMin-s1 < 0 {
				answer = append(answer, -1)
			} else {
				answer = append(answer, myMax-s1)
			}
		}
	}
	return answer
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	n, _ := readInt(reader)
	k, _ := readInt(reader)
	A := make([]int, n)
	for i := 0; i < n; i++ {
		A[i], _ = readInt(reader)
	}
	B := make([]int, n)
	for i := 0; i < n; i++ {
		B[i], _ = readInt(reader)
	}
	Q := make([][]int, k)
	for i := 0; i < k; i++ {
		l, _ := readInt(reader)
