type Dsu struct {
	parent []int
}

func NewDsu(n int) *Dsu {
	parent := make([]int, n+1)
	for i := 0; i <= n; i++ {
		parent[i] = i
	}
	return &Dsu{parent: parent}
}

func (d *Dsu) FindParent(node int) int {
	if node == d.parent[node] {
		return node
	}
	d.parent[node] = d.FindParent(d.parent[node])
	return d.parent[node]
}

func (d *Dsu) Union(u, v int) bool {
	uParent := d.FindParent(u)
	vParent := d.FindParent(v)

	if uParent != vParent {
		d.parent[vParent] = uParent
		return true
	}
	return false
}

func main() {
	n, m1, m2 := mp()[0], mp()[1], mp()[2]
	d1 := NewDsu(n)
	d2 := NewDsu(n)

	flag := 0

	for i := 0; i < m1; i++ {
		u, v := mp()[0], mp()[1]
		if !d1.Union(u, v) {
			flag = 1
		}
	}

	for i := 0; i < m2; i++ {
		u, v := mp()[0], mp()[1]
		if !d2.Union(u, v) {
			flag = 1
		}
	}

	if flag == 1 {
		fmt.Fprintln(stdout, 0)
		return
	}

	v := make([][]int, 0)

	for i := 1; i < n; i++ {
		for j := i + 1; j <= n; j++ {
			y := d1.FindParent(j)
			y1 := d1.FindParent(y)
			x := d2.FindParent(j)
			x1 := d2.FindParent(x)

			if !d1.Union(i, j) {
				d1.parent[y] = y1
			} else if !d2.Union(i, j) {
				d2.parent[x] = x1
				d1.parent[y] = y1
			} else {
				d1.Union(i, j)
				d2.Union(i, j)
				v = append(v, []int{i, j})
			}
		}
	}

	fmt.Fprintln(stdout, len(v))
	for _, pair := range v {
		fmt.Fprintf(stdout, "%d %d\n", pair[0], pair[1])
	}
	stdout.Flush()
}

