const mod = 998244353

func egcd(a, b int) (int, int, int) {
	if a == 0 {
		return b, 0, 1
	}
	g, y, x := egcd(b%a, a)
	return g, x - (b/a)*y, y
}

func modinv(a, m int) int {
	g, x, _ := egcd(a, m)
	if g != 1 {
		panic("modular inverse does not exist")
	}
	return x % m
}

func choose(n, k, p int) int {
	if k == 0 {
		return 1
	}
	x := n
	for y := n - 1; y > n-k; y-- {
		x = (x * y) % p
	}
	d := 1
	for i := 2; i <= k; i++ {
		d = (d * i) % p
	}
	return (x * modinv(d, p)) % p
}

func pow(a, b, m int) int {
	result := 1
	for b > 0 {
		if b%2 == 1 {
			result = (result * a) % m
		}
		a = (a * a) % m
		b /= 2
	}
	return result
}

func solve() {
	scanner := bufio.NewScanner(os.Stdin)
	n, _ := fmt.Scanln(scanner)
	wbPoss := n > 1
	bwPoss := n > 1
	w := 0
	b := 0
	q := 0
	free := 0
	anyBadPoss := n > 1
	for i := 0; i < n; i++ {
		scanner.Scan()
		s := scanner.Text()
		if s[0] == 'B' {
			b++
			wbPoss = false
		} else if s[0] == 'W' {
			w++
			bwPoss = false
		} else if s[0] == '?' {
			q++
		}
		if len(s) > 1 && s[1] == 'B' {
			b++
			wbPoss = false
		} else if len(s) > 1 && s[1] == 'W' {
			w++
			bwPoss = false
		} else if len(s) > 1 && s[1] == '?' {
			q++
		}
		if s == "???" {
			free++
		} else if len(s) > 0 && s[0] == s[1] {
			anyBadPoss = false
		}
	}
	wNeeded := n - w
	if wNeeded > q || wNeeded < 0 {
		fmt.Println(0)
		return
	}
	var numBadPoss int
	if anyBadPoss {
		numBadPoss = pow(2, free, mod)
		numBadPoss -= int(bwPoss) + int(wbPoss)
	} else {
		numBadPoss = 0
	}
	fmt.Println((choose(q, wNeeded, mod) - numBadPoss + mod) % mod)
}

