const BUFSIZE = 8192

type FastIO struct {
	buffer   *bufio.Reader
	newlines int
}

func NewFastIO(file *os.File) *FastIO {
	return &FastIO{
		buffer: bufio.NewReaderSize(file, BUFSIZE),
	}
}

func (f *FastIO) Read() string {
	line, _ := f.buffer.ReadString('\n')
	return line
}

func (f *FastIO) ReadLine() string {
	for f.newlines == 0 {
		line, err := f.buffer.ReadString('\n')
		if err != nil {
			break
		}
		f.newlines = strings.Count(line, "\n")
	}
	f.newlines--
	return line
}

func (f *FastIO) Flush() {
	fmt.Println()
}

type IOWrapper struct {
	buffer   *bufio.Reader
	writer   *bufio.Writer
	writable bool
	write    func(string)
	read     func() string
	readline func() string
	flush    func()
}

func NewIOWrapper(file *os.File) *IOWrapper {
	return &IOWrapper{
		buffer: NewFastIO(file),
		writer: bufio.NewWriterSize(os.Stdout, BUFSIZE),
		writable: true,
		write: func(s string) {
			fmt.Fprint(os.Stdout, s)
		},
		read: func() string {
			line, _ := f.buffer.ReadString('\n')
			return line
		},
		readline: func() string {
			line, _ := f.buffer.ReadString('\n')
			return line
		},
		flush: func() {
			os.Stdout.Sync()
		},
	}
}

