	"bufio"
	"fmt"
	"os"
	"strconv"
)

func gcd(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	n, _ := strconv.Atoi(strings.TrimSpace(reader.ReadString('\n')))
	p := make([][]int, n)
	for i := range p {
		line, _ := reader.ReadString('\n')
		nums := strings.Fields(line)
		x, _ := strconv.Atoi(nums[0])
		y, _ := strconv.Atoi(nums[1])
		p[i] = []int{x, y}
	}

	ans := 0
	cnt := 0
	r := make([][]int, n)
	for i := range r {
		r[i] = make([]int, n)
	}
	q := make([]int, n)

	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			if gcd(abs(p[i][0]-p[j][0]), abs(p[i][1]-p[j][1]))%4 == 0 {
				cnt++
				r[i][j] = 1
				q[i]++
				ans += n - 2
			}
		}
	}

	for i := 0; i < n; i++ {
		for j := 1; j < n; j++ {
			if r[i][j] == 1 {
				ans -= q[j] * 2
			}
		}
	}

	fmt.Println(ans)
}

