import (
	"strings"
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	input := scanner.Text()
	n, m := parseInts(input)

	G := make([]string, n)
	for i := 0; i < n; i++ {
		scanner.Scan()
		G[i] = scanner.Text()
	}

	F := findXCrossings(G, m-1)

	var Q int
	scanner.Scan()
	fmt.Fscanf(scanner, "%d", &Q)

	for q := 0; q < Q; q++ {
		scanner.Scan()
		input := scanner.Text()
		x1, x2 := parseInts(input)
		x1, x2 = x1-1, x2-1

		if isSafe(x1, x2, F) {
			fmt.Println("YES")
		} else {
			fmt.Println("NO")
		}
	}
}

func parseInts(s string) (int, int) {
	parts := strings.Split(s, " ")
	x1, _ := strconv.Atoi(parts[0])
	x2, _ := strconv.Atoi(parts[1])
	return x1, x2
}

func findXCrossings(G []string, m int) []int {
	var F []int
	for j := 0; j < m; j++ {
		v := false
		for i := 0; i < len(G)-1; i++ {
			if G[i+1][j] == 'X' && G[i][j+1] == 'X' {
				v = true
				break
			}
		}
		if v {
			F = append(F, j)
		}
	}
	return F
}

func isSafe(x1, x2 int, F []int) bool {
	for _, f := range F {
		if x1 <= f && f < x2 {
			return false
		}
	}
	return true
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int t = scanner.nextInt();

        for (int i = 0; i < t; i++) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            boolean[] nums = new boolean[n];
            for (int j = 0; j < m; j++) {
                scanner.next(); // Skip 'a'
                int b = scanner.nextInt() - 1;
                scanner.next(); // Skip 'c'
                nums[b] = true;
            }

            solve(nums, n);
        }

        scanner.close();
    }

    public static void solve(boolean[] nums, int n) {
        int notMiddleNode = -1;
        for (int i = 0; i < n; i++) {
            if (!nums[i]) {
                notMiddleNode = i;
                break;
            }
        }

        for (int i = 0; i < n; i++) {
            if (i != notMiddleNode) {
                System.out.println((notMiddleNode + 1) + " " + (i + 1));
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;

public class Main {
    private static final int MOD = 998244353;
    private static long[] f;
    private static long[] inv;

    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        int t = Integer.parseInt(reader.readLine());
        f = new long[100002];
        inv = new long[100002];
        f[0] = 1;
        for (int i = 1; i < 100002; i++) {
            f[i] = f[i - 1] * i % MOD;
            inv[i] = pow(i, MOD - 2, MOD);
        }
        while (t-- > 0) {
            int n = Integer.parseInt(reader.readLine());
            long[] dp1 = new long[n + 2];
            long[] dp2 = new long[n + 2];
            dp1[0] = 1;
            for (long i : readLongs(reader)) {
                dp1[(int)(i + 1)] = (dp1[(int)(i + 1)] << 1) % MOD;
                dp1[(int)(i + 1)] = (dp1[(int)(i + 1)] + dp1[(int)i]) % MOD;
                if (i > 0) {
                    dp2[(int)(i - 1)] = (dp2[(int)(i - 1)] << 1) % MOD;
                    dp2[(int)(i - 1)] = (dp2[(int)(i - 1)] + dp1[(int)(i - 1)]) % MOD;
                }
                dp2[(int)(i + 1)] = (dp2[(int)(i + 1)] << 1) % MOD;
            }
            long ans = 0;
            for (int i = 0; i <= n + 1; i++) {
                ans = (ans + dp1[i] + dp2[i]) % MOD;
            }
            writer.println((ans - 1 + MOD) % MOD);
        }
        writer.close();
    }

    private static long[] readLongs(BufferedReader reader) throws Exception {
        String line = reader.readLine();
        String[] parts = line.split(" ");
        int length = parts.length;
        long[] result = new long[length];
        for (int i = 0; i < length; i++) {
            result[i] = Long.parseLong(parts[i]);
        }
        return result;
    }

    private static long pow(long x, long y, long mod) {
        long result = 1;
        while (y > 0) {
            if ((y & 1) == 1) {
                result = result * x % mod;
            }
            y >>= 1;
            x = x * x % mod;
        }
        return result;
    }

    private static long gcd(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    private static long lcm(long x, long y) {
        return (x * y) / gcd(x, y);
    }

    private static long nCr(int x, int y) {
        return (f[x] * inv[(int) ((f[y] * f[x - y]) % MOD)] % MOD) % MOD;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static final int BUFSIZE = 8192;

    private static class FastIO extends FilterInputStream {
        private byte[] buffer;
        private int pos, len;

        public FastIO(InputStream in) {
            super(in);
            this.buffer = new byte[BUFSIZE];
            this.pos = this.len = 0;
        }

        @Override
        public int read() throws IOException {
            if (pos == len) {
                len = in.read(buffer);
                pos = 0;
                if (len <= 0)
                    return -1;
            }
            return buffer[pos++];
        }

        @Override
        public int read(byte[] b, int off, int len) throws IOException {
            int bytesRead = 0;
            while (bytesRead < len) {
                int n = in.read(b, off + bytesRead, len - bytesRead);
                if (n == -1)
                    break;
                bytesRead += n;
            }
            return bytesRead;
        }

        public String readLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = read()) != '\n' && c != -1) {
                sb.append((char) c);
            }
            return sb.toString();
        }
    }

    private static class IOWrapper extends PrintWriter {
        public IOWrapper(OutputStream out) {
            super(new BufferedOutputStream(out));
        }

        @Override
        public void print(Object obj) {
            write(obj.toString());
        }

        @Override
        public void println() {
            write('\n');
        }

        @Override
        public void close() {
            flush();
            super.close();
        }
    }

    private static FastIO in = new FastIO(System.in);
    private static IOWrapper out = new IOWrapper(System.out);

    public static int[] nextLargerElement(int[] arr, int n, boolean f) {
        Stack<Integer> s = new Stack<>();
        int[] ans = new int[n];
        Arrays.fill(ans, -1);
        for (int i = 0; i < n; i++) {
            while (!s.isEmpty() && arr[s.peek()] < arr[i]) {
                s.pop();
            }
            if (!s.isEmpty()) {
                ans[i] = s.peek();
            }
            s.push(i);
        }
        if (f) {
            for (int i = 0; i < n; i++) {
                if (ans[i] != -1) {
                    ans[i] = n - 1 - ans[i];
                }
            }
        }
        return ans;
    }

    public static int dfs(int i, List<List<Integer>> adj, int p, int ans) {
        boolean f = true;
        int a1 = 0;
        for (int j : adj.get(i)) {
            if (j != p) {
                a1 += dfs(j, adj, i, ans + 1);
                f = false;
            }
        }
        if (f) {
            a1 += ans * (ans - 1) / 2;
        }
        return a1;
    }

    public static void main(String[] args) throws IOException {
        int t = Integer.parseInt(in.readLine());
        while (t-- > 0) {
            String[] line = in.readLine().split(" ");
            int n = Integer.parseInt(line[0]);
            int s = Integer.parseInt(line[1]);
            out.println(s / ((n + 2) / 2));
        }
        out.close();
    }
}

