import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = Integer.parseInt(scanner.nextLine());
        for (int i = 0; i < t; i++) {
            solve(scanner);
        }
    }

    private static void solve(Scanner scanner) {
        int n = Integer.parseInt(scanner.nextLine());
        String[] input = scanner.nextLine().split(" ");
        int[] alst = new int[n];
        for (int j = 0; j < n; j++) {
            alst[j] = Integer.parseInt(input[j]) - 1;
        }
        int[] pos = new int[n];
        for (int i = 0; i < n; i++) {
            if ((alst[i] - i) % 2 == 1) {
                System.out.println(-1);
                return;
            }
            pos[alst[i]] = i;
        }

        java.util.ArrayList<Integer> ans = new java.util.ArrayList<>();
        for (int i = n - 1; i > 0; i -= 2) {
            int p = pos[i];
            if (p < 0 || p >= n) continue;
            ans.add(p + 1);
            for (int j = 0; j < p / 2; j++) {
                swap(alst, j, p - j);
                swap(pos, alst[j], alst[p - j]);
            }
            p = pos[i - 1];
            if (p < 0 || p >= n) continue;
            ans.add(p);
            p -= 1;
            for (int j = 0; j < p / 2; j++) {
                swap(alst, j, p - j);
                swap(pos, alst[j], alst[p - j]);
            }
            ans.add(p + 3);
            p += 2;
            if (p < 0 || p >= n) continue;
            for (int j = 0; j < p / 2; j++) {
                swap(alst, j, p - j);
                swap(pos, alst[j], alst[p - j]);
            }
            p = 2;
            if (p < 0 || p >= n) continue;
            ans.add(3);
            for (int j = 0; j < p / 2; j++) {
                swap(alst, j, p - j);
                swap(pos, alst[j], alst[p - j]);
            }
            p = i;
            if (p < 0 || p >= n) continue;
            ans.add(p + 1);
            for (int j = 0; j < p / 2; j++) {
                swap(alst, j, p - j);
                swap(pos, alst[j], alst[p - j]);
            }
        }

        System.out.println(ans.size());
        for (Integer a : ans) {
            System.out.print(a + " ");
        }
    }

    private static void swap(int[] arr, int i, int j) {
        if (i < 0 || i >= arr.length || j < 0 || j >= arr.length) return;
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = Integer.parseInt(scanner.nextLine());
        for (int tests = 0; tests < t; tests++) {
            String[] parts = scanner.nextLine().split(" ");
            int n = Integer.parseInt(parts[0]);
            int d = Integer.parseInt(parts[1]);
            int[] A = new int[n];
            String[] values = scanner.nextLine().split(" ");
            for (int i = 0; i < n; i++) {
                A[i] = Integer.parseInt(values[i]);
            }

            int[] ANS = new int[n];
            for (int i = 0; i < n; i++) {
                if (A[i] == 0) {
                    ANS[i] = 0;
                    int x = (i + d) % n;
                    int now = 1;
                    while (true) {
                        if (ANS[x] > 0 || A[x] == 0) {
                            break;
                        } else {
                            ANS[x] = now;
                            now++;
                            x = (x + d) % n;
                        }
                    }
                }
            }

            boolean hasNegativeOne = false;
            int maxAns = -1;
            for (int ans : ANS) {
                if (ans == -1) {
                    hasNegativeOne = true;
                    break;
                } else if (ans > maxAns) {
                    maxAns = ans;
                }
            }

            if (hasNegativeOne) {
                System.out.println(-1);
            } else {
                System.out.println(maxAns);
            }
        }
    }
}

