import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = Integer.parseInt(scanner.nextLine());
        for (int i = 0; i < t; i++) {
            solve(scanner);
        }
    }

    private static void solve(Scanner scanner) {
        String[] input = scanner.nextLine().split(" ");
        int n = Integer.parseInt(input[0]);
        int k = Integer.parseInt(input[1]);
        int x = Integer.parseInt(input[2]);
        String s = scanner.nextLine();

        if (!s.contains("*")) {
            System.out.println(s);
            return;
        }

        String[] stars = s.split("a");
        int[] expand = new int[stars.length];
        for (int j = 0; j < stars.length; j++) {
            expand[j] = 1 + k * stars[j].length();
        }

        long[] prods = new long[stars.length];
        prods[prods.length - 1] = expand[expand.length - 1];
        for (int j = 1; j < stars.length; j++) {
            prods[prods.length - 1 - j] = prods[prods.length - j] * expand[j];
        }

        x -= 1;

        int[] counts = new int[stars.length + 1];
        for (int j = prods.length - 1; j >= 0; j--) {
            counts[counts.length - 2 - j] = (int) (x / prods[j]);
            x -= prods[j] * counts[counts.length - 2 - j];
        }
        counts[counts.length - 1] = (int) (x % prods[0]);

        StringBuilder answer = new StringBuilder();
        int i = 1;
        int j = 0;
        while (j < s.length()) {
            if (s.charAt(j) == 'a') {
                answer.append('a');
                j++;
            } else {
                for (int m = 0; m < counts[i]; m++) {
                    answer.append('b');
                }
                i++;
                while (j < s.length() && s.charAt(j) == '*') {
                    j++;
                }
            }
        }

        System.out.println(answer.toString());
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String[] nk = reader.readLine().split(" ");
        int n = Integer.parseInt(nk[0]);
        int k = Integer.parseInt(nk[1]);
        int[] A = new int[n];
        int[] B = new int[n];
        for (int i = 0; i < n; i++) {
            A[i] = Integer.parseInt(reader.readLine());
        }
        for (int i = 0; i < n; i++) {
            B[i] = Integer.parseInt(reader.readLine());
        }
        int[][] Q = new int[k][2];
        for (int i = 0; i < k; i++) {
            String[] lr = reader.readLine().split(" ");
            Q[i][0] = Integer.parseInt(lr[0]);
            Q[i][1] = Integer.parseInt(lr[1]);
        }
        int[] answer = process(A, B, Q);
        for (int x : answer) {
            System.out.println(x);
        }
    }

    public static int[] process(int[] A, int[] B, int[][] Q) {
        int[] S = new int[A.length + 1];
        S[0] = 0;
        for (int i = 0; i < A.length; i++) {
            int ai = A[i];
            int bi = B[i];
            int di = bi - ai;
            S[i + 1] = S[i] + di;
        }
        int n = S.length;
        int p = (int) Math.pow(2, (int) Math.ceil(Math.log(n) / Math.log(2)));
        int[] minTree = new int[2 * p - 1];
        int[] maxTree = new int[2 * p - 1];
        for (int i = 0; i < p; i++) {
            if (i < n) {
                minTree[i] = S[i];
                maxTree[i] = S[i];
            } else {
                minTree[i] = Integer.MAX_VALUE;
                maxTree[i] = Integer.MIN_VALUE;
            }
        }
        for (int i = p; i < 2 * p - 1; i++) {
            int i1 = (2 * p - 2) - i;
            int j1 = 2 * i1 + 1;
            int j2 = 2 * i1 + 2;
            int iLeft = (2 * p - 2) - j1;
            int iRight = (2 * p - 2) - j2;
            minTree[i] = Math.min(minTree[iLeft], minTree[iRight]);
            maxTree[i] = Math.max(maxTree[iLeft], maxTree[iRight]);
        }
        int[] answer = new int[Q.length];
        for (int i = 0; i < Q.length; i++) {
            int l = Q[i][0];
            int r = Q[i][1];
            int s1 = S[l - 1];
            int s2 = S[r];
            if (s1 != s2) {
                answer[i] = -1;
            } else {
                int myMin = findMin(l, r, 0, p - 1, 2 * p - 2, minTree);
                int myMax = findMax(l, r, 0, p - 1, 2 * p - 2, maxTree);
                if (myMin - s1 < 0) {
                    answer[i] = -1;
                } else {
                    answer[i] = myMax - s1;
                }
            }
        }
        return answer;
    }

    public static int findMax(int l, int r, int startL, int startR, int startI, int[] maxTree) {
        if (startI < 0) {
            return Integer.MIN_VALUE;
        }
        if (l == r) {
            return maxTree[startI];
        }
        if (l == startL && r == startR) {
            return maxTree[startI];
        }
        int i1 = (2 * maxTree.length - 2) - startI;
        int iLeft = (2 * maxTree.length - 2) - (2 * i1 + 2);
        int iRight = (2 * maxTree.length - 2) - (2 * i1 + 1);
        int m1 = (startL + startR) / 2;
        if (l > m1) {
            return findMax(l, r, m1 + 1, startR, iRight, maxTree);
        } else if (r <= m1) {
            return findMax(l, r, startL, m1, iLeft, maxTree);
        } else {
            int max1 = findMax(l, m1, startL, m1, iLeft, maxTree);
            int max2 = findMax(m1 + 1, r, m1 + 1, startR, iRight, maxTree);
            return Math.max(max1, max2);
        }
    }

    public static int findMin(int l, int r, int startL, int startR, int startI, int[] minTree) {
        if (startI < 0) {
            return Integer.MAX_VALUE;
        }
        if (l == r) {
            return minTree[startI];
        }
        if (l == startL && r == startR) {
            return minTree[startI];
        }
        int i1 = (2 * minTree.length - 2) - startI;
        int iLeft = (2 * minTree.length - 2) - (2 * i1 + 2);
        int iRight = (2 * minTree.length - 2) - (2 * i1 + 1);
        int m1 = (startL + startR) / 2;
        if (l > m1) {
            return findMin(l, r, m1 + 1, startR, iRight, minTree);
        } else if (r <= m1) {
            return findMin(l, r, startL, m1, iLeft, minTree);
        } else {
            int min1 = findMin(l, m1, startL, m1, iLeft, minTree);
            int min2 = findMin(m1 + 1, r, m1 + 1, startR, iRight, minTree);
            return Math.min(min1, min2);
        }
    }
}

