            int n = Integer.parseInt(nm[0]);
            int m = Integer.parseInt(nm[1]);
            int[][] d = new int[n][m];
            for (int j = 0; j < n; j++) {
                String line = scanner.nextLine();
                for (int k = 0; k < m; k++) {
                    char c = line.charAt(k);
                    if (c == 'R') d[j][k] = -1;
                    else if (c == 'U') d[j][k] = -2;
                    else if (c == 'L') d[j][k] = -3;
                    else d[j][k] = -4;
                }
            }
            int r = 0;
            int[] pos = {0, 0};
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < m; k++) {
                    int a = j, b = k, p = d[j][k], c = 0;
                    java.util.ArrayList<int[]> st = new java.util.ArrayList<>();
                    while (p < 0) {
                        d[a][b] = 0;
                        st.add(new int[]{a, b});
                        if (p == -1) b += 1;
                        else if (p == -2) a -= 1;
                        else if (p == -3) b -= 1;
                        else a += 1;
                        c += 1;
                        if (0 <= a && a < n && 0 <= b && b < m) {
                            p = d[a][b];
                        } else {
                            for (int ii = 0; ii < st.size(); ii++) {
                                int[] xy = st.get(ii);
                                d[xy[0]][xy[1]] = c - ii;
                            }
                            p = -1;
                            break;
                        }
                    }
                    if (p == 0) {
                        int jj = 0, flag = 0;
                        for (int ii = 0; ii < st.size(); ii++) {
                            int[] xy = st.get(ii);
                            d[xy[0]][xy[1]] = (c - jj) * (flag == 0 ? 1 : -1);
                            if (xy[0] == a && xy[1] == b) flag = 1; jj = ii;
                        }
                    }
                    if (p > 0) {
                        for (int ii = 0; ii < st.size(); ii++) {
                            int[] xy = st.get(ii);
                            d[xy[0]][xy[1]] = p + c - ii;
                        }
                    }
                    if (d[j][k] > r) {
                        r = d[j][k];
                        pos[0] = j;
                        pos[1] = k;
                    }
                }
            }
            System.out.println((pos[0] + 1) + " " + (pos[1] + 1) + " " + r);
        }
    }
