import java.io.*;
import java.util.*;

public class Main {
    private static final int MOD = 1000000007;
    private static final long INF = (long) (1 << 60);

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);

        String[] line = reader.readLine().split(" ");
        int n = Integer.parseInt(line[0]);
        int m1 = Integer.parseInt(line[1]);
        int m2 = Integer.parseInt(line[2]);

        Dsu d1 = new Dsu(n);
        Dsu d2 = new Dsu(n);
        d1.makeSet();
        d2.makeSet();

        int flag = 0;
        for (int i = 0; i < m1; i++) {
            line = reader.readLine().split(" ");
            int u = Integer.parseInt(line[0]);
            int v = Integer.parseInt(line[1]);
            if (d1.union(u, v) == -1) {
                flag = 1;
            }
        }
        for (int i = 0; i < m2; i++) {
            line = reader.readLine().split(" ");
            int u = Integer.parseInt(line[0]);
            int v = Integer.parseInt(line[1]);
            if (d2.union(u, v) == -1) {
                flag = 1;
            }
        }
        if (flag != 0) {
            writer.println(0);
            writer.close();
            return;
        }

        List<int[]> v = new ArrayList<>();
        for (int i = 1; i < n; i++) {
            for (int j = i + 1; j <= n; j++) {
                int y = d1.findParent(j);
                int y1 = d1.findParent(y);
                int x = d2.findParent(j);
                int x1 = d2.findParent(x);

                if (d1.union(i, j) == -1) {
                    d1.parent[y] = y1;
                } else if (d2.union(i, j) == -1) {
                    d2.parent[x] = x1;
                    d1.parent[y] = y1;
                } else {
                    d1.union(i, j);
                    d2.union(i, j);
                    v.add(new int[]{i, j});
                }
            }
        }

        writer.println(v.size());
        for (int[] edge : v) {
            writer.print(edge[0]);
            writer.print(" ");
            writer.println(edge[1]);
        }
        writer.close();
    }

    private static class Dsu {
        int[] parent;

        public Dsu(int n) {
            this.parent = new int[n + 1];
        }

        public void makeSet() {
            for (int i = 1; i <= parent.length - 1; i++) {
                parent[i] = i;
            }
        }

        public int findParent(int node) {
            if (node == parent[node]) {
                return node;
            }
            parent[node] = findParent(parent[node]);
            return parent[node];
        }

        public int union(int u, int v) {
            int uParent = findParent(u);
            int vParent = findParent(v);

            if (uParent != vParent) {
                parent[vParent] = uParent;
                return -1;
            }
            return 0;
        }
    }

    private static String[] readLine(BufferedReader reader) throws IOException {
        return reader.readLine().split(" ");
    }
}

