import java.util.Scanner;

public class Main {
    private static final int MOD = 998244353;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        boolean wbPoss = n > 1;
        boolean bwPoss = n > 1;
        int w = 0;
        int b = 0;
        int q = 0;
        int free = 0;
        boolean anyBadPoss = n > 1;

        for (int i = 0; i < n; i++) {
            String s = scanner.next();
            if (s.charAt(0) == 'B') {
                b++;
                wbPoss = false;
            } else if (s.charAt(0) == 'W') {
                w++;
                bwPoss = false;
            } else if (s.charAt(0) == '?') {
                q++;
            }
            if (s.charAt(1) == 'B') {
                b++;
                wbPoss = false;
            } else if (s.charAt(1) == 'W') {
                w++;
                bwPoss = false;
            } else if (s.charAt(1) == '?') {
                q++;
            }
            if (s.equals("??")) {
                free++;
            } else if (s.charAt(0) == s.charAt(1)) {
                anyBadPoss = false;
            }
        }

        int wNeeded = n - w;
        if (wNeeded > q || wNeeded < 0) {
            System.out.println(0);
            return;
        }

        long numBadPoss = 0;
        if (anyBadPoss) {
            numBadPoss = pow(2, free, MOD);
            numBadPoss -= bwPoss ? 1 : 0;
            numBadPoss -= wbPoss ? 1 : 0;
        }

        System.out.println((choose(q, wNeeded, MOD) - numBadPoss + MOD) % MOD);
    }

    private static long egcd(long a, long b) {
        if (a == 0) {
            return b;
        } else {
            long g = egcd(b % a, a);
            return g;
        }
    }

    private static long modinv(long a, long m) {
        long[] result = extendedGCD(a, m);
        if (result[0] != 1) {
            throw new RuntimeException("modular inverse does not exist");
        } else {
            return (result[1] + m) % m;
        }
    }

    private static long choose(int n, int k, int p) {
        if (k == 0) {
            return 1;
        }
        long x = n;
        for (int y = n - 1; y > n - k; y--) {
            x = x * y % p;
        }
        long d = 1;
        for (int i = 2; i <= k; i++) {
            d = d * i % p;
        }
        return x * modinv(d, p) % p;
    }

    private static long pow(long base, int exp, int mod) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    private static long[] extendedGCD(long a, long b) {
        if (a == 0) {
            return new long[]{b, 0, 1};
        } else {
            long[] result = extendedGCD(b % a, a);
            long temp = result[1];
            result[1] = result[2] - (b / a) * result[1];
            result[2] = temp;
            return result;
        }
    }
}

