                if (i > 0)
                {
                    dp2[i - 1] = (dp2[i - 1] << 1) % mod;
                    dp2[i - 1] = (dp2[i - 1] + dp1[i - 1]) % mod;
                }
                dp2[i + 1] = (dp2[i + 1] << 1) % mod;
            }

            long ans = 0;
            for (int i = 0; i <= n + 1; i++)
            {
                ans = (ans + dp1[i] + dp2[i]) % mod;
            }
            Console.WriteLine((ans - 1 + mod) % mod);
        }
    }

    private static long Power(long x, int y)
    {
        long result = 1;
        while (y > 0)
        {
            if ((y & 1) == 1)
                result = result * x % mod;
            y >>= 1;
            x = x * x % mod;
        }
        return result;
    }

    private static int[] ReadInts()
    {
        string line = Console.ReadLine();
        return Array.ConvertAll(line.Split(), int.Parse);
    }
}

