            }
            pos[alst[i]] = i;
        }

        List<int> ans = new List<int>();
        for (int i = n - 1; i > 0; i -= 2)
        {
            int p = pos[i];
            if (p >= alst.Count) continue; // Check if index is out of range
            ans.Add(p + 1);
            for (int j = 0; j < p / 2; j++)
            {
                Swap(alst, j, p - j);
                Swap(pos, alst[j], alst[p - j]);
            }
            p = pos[i - 1];
            if (p >= alst.Count) continue; // Check if index is out of range
            ans.Add(p);
            p -= 1;
            for (int j = 0; j < p / 2; j++)
            {
                Swap(alst, j, p - j);
                Swap(pos, alst[j], alst[p - j]);
            }
            ans.Add(p + 3);
            p += 2;
            if (p >= alst.Count) continue; // Check if index is out of range
            for (int j = 0; j < p / 2; j++)
            {
                Swap(alst, j, p - j);
                Swap(pos, alst[j], alst[p - j]);
            }
            p = 2;
            ans.Add(3);
            if (p >= alst.Count) continue; // Check if index is out of range
            for (int j = 0; j < p / 2; j++)
            {
                Swap(alst, j, p - j);
                Swap(pos, alst[j], alst[p - j]);
            }
            p = i;
            ans.Add(p + 1);
            if (p >= alst.Count) continue; // Check if index is out of range
            for (int j = 0; j < p / 2; j++)
            {
                Swap(alst, j, p - j);
                Swap(pos, alst[j], alst[p - j]);
            }
        }

