using System.Text;

class FastIO : TextReader
{
    private const int BUFSIZE = 8192;
    private byte[] buffer = new byte[BUFSIZE];
    private int ptr = 0, len = 0;
    private Stream stream;

    public FastIO(Stream stream)
    {
        this.stream = stream;
    }

    public override int ReadByte()
    {
        if (ptr == len) { FillBuffer(); }
        return buffer[ptr++];
    }

    private void FillBuffer()
    {
        ptr = 0;
        len = stream.Read(buffer, 0, BUFSIZE);
    }

    public override string ReadLine()
    {
        var sb = new StringBuilder();
        while (true)
        {
            int b = ReadByte();
            if (b == '\n' || b == -1) break;
            sb.Append((char)b);
        }
        return sb.ToString();
    }
}

class IOWrapper : TextReader
{
    private FastIO fastIO;

    public IOWrapper(Stream stream)
    {
        fastIO = new FastIO(stream);
    }

    public override int ReadByte()
    {
        return fastIO.ReadByte();
    }

    public override string ReadLine()
    {
        return fastIO.ReadLine();
    }
}

