class Program
{
    static void Main()
    {
        int testCases = int.Parse(Console.ReadLine());
        for (int i = 0; i < testCases; i++)
        {
            Solve();
        }
    }

    static void Solve()
    {
        string[] input = Console.ReadLine().Split(' ');
        int n = int.Parse(input[0]);
        int k = int.Parse(input[1]);
        int x = int.Parse(input[2]);
        string s = Console.ReadLine();

        if (!s.Contains('*'))
        {
            Console.WriteLine(s);
            return;
        }

        List<string> stars = new List<string>();
        foreach (var part in s.Split('a'))
        {
            if (!string.IsNullOrEmpty(part))
                stars.Add(part);
        }

        List<int> expand = new List<int>();
        foreach (var star in stars)
        {
            expand.Add(1 + k * star.Length);
        }

        List<int> prods = new List<int>();
        prods.Add(expand[expand.Count - 1]);
        for (int i = 1; i < expand.Count; i++)
        {
            prods.Add(prods[prods.Count - 1] * expand[expand.Count - i - 1]);
        }

        x -= 1;

        List<int> counts = new List<int>();
        int j = prods.Count - 1;
        while (j >= 0)
        {
            if (prods[j] == 0) continue; // Skip zero to avoid division by zero
            counts.Add(x / prods[j]);
            x -= prods[j] * (x / prods[j]);
            j--;
        }
        counts.Add(x % prods[0]);

        string answer = "";
        int aIndex = 1;
        int sIndex = 0;
        while (sIndex < s.Length)
        {
            if (s[sIndex] == 'a')
            {
                answer += "a";
                sIndex++;
            }
            else
            {
                answer += new string('b', counts[aIndex]);
                aIndex++;
                while (sIndex < s.Length && s[sIndex] == '*')
                {
                    sIndex++;
                }
            }
        }

        Console.WriteLine(answer);
    }
}

