class Program
{
    static void Main()
    {
        int n = int.Parse(Console.ReadLine());
        int k = int.Parse(Console.ReadLine());
        List<int> A = new List<int>(n);
        List<int> B = new List<int>(n);
        for (int i = 0; i < n; i++)
        {
            A.Add(int.Parse(Console.ReadLine()));
        }
        for (int i = 0; i < n; i++)
        {
            B.Add(int.Parse(Console.ReadLine()));
        }
        List<List<int>> Q = new List<List<int>>(k);
        for (int i = 0; i < k; i++)
        {
            string[] query = Console.ReadLine().Split();
            int l = int.Parse(query[0]) - 1; // Adjust index to be zero-based
            int r = int.Parse(query[1]);
            Q.Add(new List<int> { l, r });
        }
        List<int> answer = Process(A, B, Q);
        foreach (int x in answer)
        {
            Console.WriteLine(x);
        }
    }

    static List<int> Process(List<int> A, List<int> B, List<List<int>> Q)
    {
        List<int> S = new List<int> { 0 };
        int n = A.Count;
        for (int i = 0; i < n; i++)
        {
            int ai = A[i];
            int bi = B[i];
            int di = bi - ai;
            S.Add(S[S.Count - 1] + di);
        }
        n = S.Count;
        int p = (int)Math.Ceiling(Math.Log(n, 2));
        p = (int)Math.Pow(2, p);
        List<int> minTree = new List<int>(new int[2 * p - 1]);
        List<int> maxTree = new List<int>(new int[2 * p - 1]);
        for (int i = 0; i < p; i++)
        {
            if (i < n)
            {
                minTree[i] = S[i];
                maxTree[i] = S[i];
            }
            else
            {
                minTree[i] = int.MaxValue;
                maxTree[i] = -1 * int.MaxValue;
            }
        }
        for (int i = p; i < 2 * p - 1; i++)
        {
            int i1 = (2 * p - 2) - i;
            int j1 = 2 * i1 + 1;
            int j2 = 2 * i1 + 2;
            int iLeft = (2 * p - 2) - j1;
            int iRight = (2 * p - 2) - j2;
            minTree[i] = Math.Min(minTree[iLeft], minTree[iRight]);
            maxTree[i] = Math.Max(maxTree[iLeft], maxTree[iRight]);
        }
        List<int> answer = new List<int>();
        foreach (List<int> query in Q)
        {
            int l = query[0];
            int r = query[1];
            int s1 = S[l - 1];
            int s2 = S[r];
            if (s1 != s2)
            {
                answer.Add(-1);
            }
            else
            {
                int myMin = FindMin(l, r, 0, p - 1, 2 * p - 2, minTree);
                int myMax = FindMax(l, r, 0, p - 1, 2 * p - 2, maxTree);
                if (myMin - s1 < 0)
                {
                    answer.Add(-1);
                }
                else
                {
                    answer.Add(myMax - s1);
                }
            }
        }
        return answer;
    }

    static int FindMax(int l, int r, int startL, int startR, int startI, List<int> maxTree)
    {
        if (startI < 0)
        {
            return int.MinValue;
        }
        if (l == r)
        {
            return maxTree[l];
        }
        if (l == startL && r == startR)
        {
            return maxTree[startI];
        }
        int m1 = (startL + startR) / 2;
        if (l > m1)
        {
            return FindMax(l, r, m1 + 1, startR, 2 * startI + 2, maxTree);
        }
        else if (r <= m1)
        {
            return FindMax(l, r, startL, m1, 2 * startI + 1, maxTree);
        }
        else
        {
            int max1 = FindMax(l, m1, startL, m1, 2 * startI + 1, maxTree);
            int max2 = FindMax(m1 + 1, r, m1 + 1, startR, 2 * startI + 2, maxTree);
            return Math.Max(max1, max2);
        }
    }

    static int FindMin(int l, int r, int startL, int startR, int startI, List<int> minTree)
    {
        if (startI < 0)
        {
            return int.MaxValue;
        }
        if (l == r)
        {
            return minTree[l];
        }
        if (l == startL && r == startR)
        {
            return minTree[startI];
        }
        int m1 = (startL + startR) / 2;
        if (l > m1)
        {
            return FindMin(l, r, m1 + 1, startR, 2 * startI + 2, minTree);
        }
        else if (r <= m1)
        {
            return FindMin(l, r, startL, m1, 2 * startI + 1, minTree);
        }
        else
        {
            int min1 = FindMin(l, m1, startL, m1, 2 * startI + 1, minTree);
            int min2 = FindMin(m1 + 1, r, m1 + 1, startR, 2 * startI + 2, minTree);
            return Math.Min(min1, min2);
        }
    }
}

