class Program
{
    static void Main()
    {
        int[] input = ReadLine().Split(' ').Select(int.Parse).ToArray();
        int n = input[0];
        int m1 = input[1];
        int m2 = input[2];

        Dsu d1 = new Dsu(n);
        Dsu d2 = new Dsu(n);

        d1.MakeSet();
        d2.MakeSet();

        bool flag = false;

        for (int i = 0; i < m1; i++)
        {
            int[] uv = ReadLine().Split(' ').Select(int.Parse).ToArray();
            if (d1.Union(uv[0], uv[1]) == -1)
                flag = true;
        }

        for (int i = 0; i < m2; i++)
        {
            int[] uv = ReadLine().Split(' ').Select(int.Parse).ToArray();
            if (d2.Union(uv[0], uv[1]) == -1)
                flag = true;
        }

        if (flag)
        {
            Console.WriteLine(0);
            return;
        }

        List<int[]> v = new List<int[]>();

        for (int i = 1; i < n; i++)
        {
            for (int j = i + 1; j <= n; j++)
            {
                int y = d1.FindParent(j);
                int y1 = d1.FindParent(y);
                int x = d2.FindParent(j);
                int x1 = d2.FindParent(x);

                if (d1.Union(i, j) == -1)
                    d1.Parent[y] = y1;
                else if (d2.Union(i, j) == -1)
                {
                    d2.Parent[x] = x1;
                    d1.Parent[y] = y1;
                }
                else
                {
                    d1.Union(i, j);
                    d2.Union(i, j);
                    v.Add(new int[] { i, j });
                }
            }
        }

        Console.WriteLine(v.Count);
        foreach (var pair in v)
        {
            Console.WriteLine($"{pair[0]} {pair[1]}");
        }
    }

    static string ReadLine() => Console.ReadLine();

    class Dsu
    {
        public int[] Parent;

        public Dsu(int n)
        {
            Parent = new int[n + 1];
        }

        public void MakeSet()
        {
            for (int i = 1; i <= Parent.Length - 1; i++)
                Parent[i] = i;
        }

        public int FindParent(int node)
        {
            if (node == Parent[node])
                return node;

            Parent[node] = FindParent(Parent[node]);
            return Parent[node];
        }

        public int Union(int u, int v)
        {
            int uParent = FindParent(u);
            int vParent = FindParent(v);

            if (uParent != vParent)
            {
                Parent[vParent] = uParent;
                return -1;
            }
            else
            {
                return 0;
            }
        }
    }
}

