class FastIO
{
    private readonly Stream _stream;
    private readonly byte[] _buffer = new byte[8192];
    private int _bufferPointer;
    private int _bufferLength;

    public FastIO(Stream stream)
    {
        _stream = stream;
    }

    public string ReadLine()
    {
        var sb = new StringBuilder();
        while (true)
        {
            int b = ReadByte();
            if (b == -1 || b == '\n')
                break;
            sb.Append((char)b);
        }
        return sb.ToString();
    }

    private int ReadByte()
    {
        if (_bufferPointer >= _bufferLength)
        {
            _bufferLength = _stream.Read(_buffer, 0, _buffer.Length);
            _bufferPointer = 0;
            if (_bufferLength == 0)
                return -1;
        }
        return _buffer[_bufferPointer++];
    }

    public void Write(string s)
    {
        foreach (var b in System.Text.Encoding.ASCII.GetBytes(s))
        {
            _stream.WriteByte(b);
        }
    }

    public void WriteLine(string s)
    {
        Write(s + "\n");
    }

    public void Flush()
    {
        _stream.Flush();
    }
}

using System;

class Program
{
    private const long Mod = 998244353;

    public static void Main(string[] args)
    {
        Solve();
    }

    private static (long, long, long) Egcd(long a, long b)
    {
        if (a == 0)
            return (b, 0, 1);
        else
        {
            var (g, y, x) = Egcd(b % a, a);
            return (g, x - (b / a) * y, y);
        }
    }

    private static long Modinv(long a, long m)
    {
        var (g, x, _) = Egcd(a, m);
        if (g != 1)
            throw new Exception("modular inverse does not exist");
        else
            return x % m;
    }

    private static long Choose(long n, long k, long p)
    {
        if (k == 0)
            return 1;
        long x = n;
        for (long y = n - 1; y >= n - k; y--)
            x = x * y % p;
        long d = 1;
        for (long i = 2; i <= k; i++)
            d = d * i % p;
        return x * Modinv(d, p) % p;
    }

    private static void Solve()
    {
        int n = int.Parse(Console.ReadLine());
        bool wbPoss = n > 1;
        bool bwPoss = n > 1;
        long w = 0;
        long b = 0;
        long q = 0;
        long free = 0;
        bool anyBadPoss = n > 1;
        for (int i = 0; i < n; i++)
        {
            string s = Console.ReadLine().Trim();
            if (s[0] == 'B')
            {
                b += 1;
                wbPoss = false;
            }
            else if (s[0] == 'W')
            {
                w += 1;
                bwPoss = false;
            }
            else if (s[0] == '?')
            {
                q += 1;
            }
            if (s[1] == 'B')
            {
                b += 1;
                bwPoss = false;
            }
            else if (s[1] == 'W')
            {
                w += 1;
                bwPoss = false;
            }
            else if (s[1] == '?')
            {
                q += 1;
            }
            if (s == "??")
            {
                free += 1;
            }
            else if (s[0] == s[1])
            {
                anyBadPoss = false;
            }
        }
        long wNeeded = n - w;
        if (wNeeded > q || wNeeded < 0)
        {
            Console.WriteLine(0);
            return;
        }
        long numBadPoss = 0;
        if (anyBadPoss)
        {
            numBadPoss = Pow(2, free, Mod);
            if (bwPoss) numBadPoss -= 1;
            if (wbPoss) numBadPoss -= 1;
        }
        Console.WriteLine((Choose(q, wNeeded, Mod) - numBadPoss + Mod) % Mod);
    }

    private static long Pow(long x, long y, long p)
    {
        long res = 1;
        x = x % p;
        while (y > 0)
        {
            if ((y & 1) == 1)
                res = (res * x) % p;
            y = y >> 1;
            x = (x * x) % p;
        }
        return res;
    }
}

