class FastIO : Stream
{
    private const int BUFSIZE = 8192;
    private readonly byte[] buffer = new byte[BUFSIZE];
    private int ptr = 0, len = 0;
    private bool eof = false;

    public FastIO(Stream stream)
    {
        this.stream = stream;
    }

    private void FillBuffer()
    {
        if (eof) return;
        try
        {
            len = stream.Read(buffer, 0, BUFSIZE);
            ptr = 0;
            if (len == 0) eof = true;
        }
        catch { eof = true; }
    }

    public override int ReadByte()
    {
        if (ptr >= len)
        {
            FillBuffer();
            if (eof) return -1;
        }
        return buffer[ptr++];
    }

    public override string ReadLine()
    {
        var sb = new StringBuilder();
        while (true)
        {
            int b = ReadByte();
            if (b == '\n' || b == -1) break;
            sb.Append((char)b);
        }
        return sb.ToString();
    }

    public override void Write(byte[] buffer, int offset, int count)
    {
        stream.Write(buffer, offset, count);
    }

    public override long Length => throw new NotSupportedException();

    public override bool CanWrite => true;

    public override bool CanRead => true;

    public override void Flush()
    {
        if (CanWrite)
            stream.Flush();
    }

    public override long Position
    {
        get => throw new NotSupportedException();
        set => throw new NotSupportedException();
    }

    private Stream stream;
}

class IOWrapper : TextWriter
{
    private readonly FastIO fastIO;

    public IOWrapper(Stream stream)
    {
        fastIO = new FastIO(stream);
    }

    public override string ReadLine()
    {
        return fastIO.ReadLine();
    }

    public override void Write(string value)
    {
        fastIO.Write(value);
    }

    public override Encoding Encoding => Encoding.ASCII;

    protected override void Dispose(bool disposing)
    {
        base.Dispose(disposing);
        fastIO.Dispose();
    }
}

