use std::collections::VecDeque;

fn next_larger_element(arr: &mut Vec<i32>, n: usize, f: bool) -> Vec<usize> {
    let mut s = VecDeque::new();
    let mut ans = vec![-1; n];
    for i in 0..n {
        while !s.is_empty() && arr[s.back().unwrap()] < arr[i] {
            s.pop_back();
        }
        if !s.is_empty() {
            ans[i] = *s.back().unwrap();
        }
        s.push_back(i);
    }
    if f {
        for i in 0..n {
            if ans[i] != -1 {
                ans[i] = n as usize - 1 - ans[i];
            }
        }
    }
    ans
}

fn dfs(i: usize, adj: &Vec<Vec<usize>>, p: usize, ans: usize) -> usize {
    let mut f = true;
    let mut a1 = 0;
    for j in &adj[i] {
        if *j != p {
            a1 += dfs(*j, adj, i, ans + 1);
            f = false;
        }
    }
    if f {
        a1 += ans * (ans - 1) / 2;
    }
    a1
}

