        .map(|x| x.parse::<usize>().unwrap() - 1)
        .collect();

    if (0..n).any(|i| (alst[i] as isize - i as isize) % 2 != 0) {
        println!("-1");
        return;
    }

    let mut pos = vec![-1; n];
    for (i, &a) in alst.iter().enumerate() {
        pos[a] = i as isize;
    }

    let mut ans = Vec::new();
    for i in (1..n).rev().step_by(2) {
        let mut p = pos[i] as usize;
        ans.push(p + 1);
        for j in 0..p / 2 {
            alst.swap(j, p - j);
            pos[alst[j]] = j as isize;
            pos[alst[p - j]] = (p - j) as isize;
        }

        let mut p = pos[i - 1] as usize;
        ans.push(p);
        if p > 0 {
            p -= 1;
            for j in 0..p / 2 {
                alst.swap(j, p - j);
                pos[alst[j]] = j as isize;
                pos[alst[p - j]] = (p - j) as isize;
            }
        }

        ans.push(p + 3);
        if p < n - 1 {
            p += 2;
            for j in 0..p / 2 {
                alst.swap(j, p - j);
                pos[alst[j]] = j as isize;
                pos[alst[p - j]] = (p - j) as isize;
            }
        }

        ans.push(3);
        if p < n - 1 {
            let mut p = i;
            ans.push(p + 1);
            for j in 0..p / 2 {
                alst.swap(j, p - j);
                pos[alst[j]] = j as isize;
                pos[alst[p - j]] = (p - j) as isize;
            }
        }
    }

