fn solve() {
    let mut input = String::new();
    io::stdin().read_line(&mut input).unwrap();
    let parts: Vec<&str> = input.split_whitespace().collect();
    let n: usize = parts[0].parse().unwrap();
    let k: usize = parts[1].parse().unwrap();
    let mut x: usize = parts[2].parse().unwrap();

    let mut s = String::new();
    io::stdin().read_line(&mut s).unwrap();
    s.pop(); // Remove the newline character

    if !s.contains('*') {
        println!("{}", s);
        return;
    }

    let stars: Vec<&str> = s.split('a').filter(|&x| !x.is_empty()).collect();

    let expand: Vec<usize> = stars.iter().map(|star| 1 + k * star.len()).collect();
    let mut prods: Vec<usize> = vec![expand.last().unwrap().clone()];
    for i in (0..stars.len() - 1).rev() {
        prods.push(prods.last().unwrap() * expand[i]);
    }

    x -= 1;

    let mut counts: Vec<usize> = Vec::new();
    for prod in prods.iter().rev() {
        counts.push(x / prod);
        x -= prod * (x / prod);
    }
    counts.push(x % prods[0]);

    let mut answer = String::new();
    let mut i = 1;
    let mut j = 0;
    while j < s.len() {
        if s.chars().nth(j).unwrap() == 'a' {
            answer.push('a');
            j += 1;
        } else {
            for _ in 0..counts[i] {
                answer.push('b');
            }
            i += 1;
            while j < s.len() && s.chars().nth(j).unwrap() == '*' {
                j += 1;
            }
        }
    }

    println!("{}", answer);
}

