fn process(A: &[i32], B: &[i32], Q: &[(usize, usize)]) -> Vec<i32> {
    let n = A.len();
    let mut S = vec![0];
    for i in 0..n {
        let ai = A[i];
        let bi = B[i];
        let di = bi - ai;
        S.push(S.last().unwrap() + di);
    }

    let p = (S.len() as f64).log2().ceil() as usize;
    let p = 1 << p;
    let mut min_tree = vec![None; 2 * p - 1];
    let mut max_tree = vec![None; 2 * p - 1];

    for i in 0..p {
        if i < n {
            min_tree[i] = Some(S[i]);
            max_tree[i] = Some(S[i]);
        } else {
            min_tree[i] = Some(i32::MAX);
            max_tree[i] = Some(-i32::MAX);
        }
    }

    for i in p..(2 * p - 1) {
        let i1 = (2 * p - 2) - i;
        let j1 = 2 * i1 + 1;
        let j2 = 2 * i1 + 2;
        let i_left = (2 * p - 2) - j1;
        let i_right = (2 * p - 2) - j2;

        min_tree[i] = Some(min_tree[i_left].unwrap().min(min_tree[i_right].unwrap()));
        max_tree[i] = Some(max_tree[i_left].unwrap().max(max_tree[i_right].unwrap()));
    }

    fn find_max(l: usize, r: usize, start_l: usize, start_r: usize, start_i: usize, min_tree: &Vec<Option<i32>>) -> Option<i32> {
        if l > r || start_l > start_r {
            return None;
        }
        if l == r {
            return min_tree[start_i];
        }

        let i1 = (2 * p - 2) - start_i;
        let i_l = (2 * p - 2) - (2 * i1 + 2);
        let i_r = (2 * p - 2) - (2 * i1 + 1);
        let m1 = (start_l + start_r) / 2;

        if l > m1 {
            find_max(l, r, m1 + 1, start_r, i_r, min_tree)
        } else if r <= m1 {
            find_max(l, r, start_l, m1, i_l, min_tree)
        } else {
            let max1 = find_max(l, m1, start_l, m1, i_l, min_tree);
            let max2 = find_max(m1 + 1, r, m1 + 1, start_r, i_r, min_tree);
            Some(max1.unwrap().max(max2.unwrap()))
        }
    }

    fn find_min(l: usize, r: usize, start_l: usize, start_r: usize, start_i: usize, max_tree: &Vec<Option<i32>>) -> Option<i32> {
        if l > r || start_l > start_r {
            return None;
        }
        if l == r {
            return max_tree[start_i];
        }

        let i1 = (2 * p - 2) - start_i;
        let i_l = (2 * p - 2) - (2 * i1 + 2);
        let i_r = (2 * p - 2) - (2 * i1 + 1);
        let m1 = (start_l + start_r) / 2;

        if l > m1 {
            find_min(l, r, m1 + 1, start_r, i_r, max_tree)
        } else if r <= m1 {
            find_min(l, r, start_l, m1, i_l, max_tree)
        } else {
            let min1 = find_min(l, m1, start_l, m1, i_l, max_tree);
            let min2 = find_min(m1 + 1, r, m1 + 1, start_r, i_r, max_tree);
            Some(min1.unwrap().min(min2.unwrap()))
        }
    }

    let mut answer = vec![];
    for &(l, r) in Q {
        let s1 = S[l - 1];
        let s2 = S[r];
        if s1 != s2 {
            answer.push(-1);
        } else {
            let my_min = find_min(l, r, 0, p - 1, 2 * p - 2, &max_tree).unwrap();
            let my_max = find_max(l, r, 0, p - 1, 2 * p - 2, &min_tree).unwrap();
            if my_min - s1 < 0 {
                answer.push(-1);
            } else {
                answer.push(my_max - s1);
            }
        }
    }

    answer
}

