    let mut lines = input.lines();

    let t: usize = lines.next().unwrap().parse().unwrap();
    for _ in 0..t {
        lines.next(); // Skip the empty line
        let nm: Vec<usize> = lines.next().unwrap().split_whitespace()
            .map(|x| x.parse().unwrap()).collect();
        let n = nm[0];
        let m = nm[1];

        let mut d: Vec<Vec<isize>> = vec![vec![-1; m]; n];
        for i in 0..n {
            let row = lines.next().unwrap().chars()
                .map(|c| match c {
                    'R' => -1,
                    'U' => -2,
                    'L' => -3,
                    _ => -4,
                }).collect();
            d[i] = row;
        }

        let mut r = 0;
        let mut pos = (0, 0);
        for i in 0..n {
            for j in 0..m {
                let mut a = i;
                let mut b = j;
                let mut p = d[a][b];
                let mut c = 0;
                let mut st: Vec<(usize, usize)> = vec![];

                while p < 0 {
                    d[a][b] = 0;
                    st.push((a, b));
                    if p == -1 { b += 1; }
                    else if p == -2 { a -= 1; }
                    else if p == -3 { b -= 1; }
                    else { a += 1; }
                    c += 1;
                    if 0 <= a && a < n && 0 <= b && b < m {
                        p = d[a][b];
                    } else {
                        for (ii, &(x, y)) in st.iter().enumerate() {
                            d[x][y] = c - ii as isize;
                        }
                        p = -1;
                        break;
                    }
                }

                if p == 0 {
                    let mut jj = 0;
                    let mut flag = false;
                    for (ii, &(x, y)) in st.iter().enumerate() {
                        d[x][y] = if flag { c - jj as isize } else { c - ii as isize };
                        if x == a && y == b { flag = true; jj = ii; }
                    }
                }

                if p > 0 {
                    for (ii, &(x, y)) in st.iter().enumerate() {
                        d[x][y] = p + c - ii as isize;
                    }
                }

                if d[i][j] > r as isize { r = d[i][j]; pos = (i, j); }
            }
        }

        println!("{} {} {}", pos.0 + 1, pos.1 + 1, r);
    }
}

