const int mod = 998244353;
int N = 1000002;
vector<long long> f(N), inv(N);

void precompute() {
    f[0] = 1;
    for (int i = 1; i < N; ++i) {
        f[i] = f[i - 1] * i % mod;
    }
    inv[N - 1] = power(f[N - 1], mod - 2, mod);
    for (int i = N - 2; i >= 0; --i) {
        inv[i] = inv[i + 1] * (i + 1) % mod;
    }
}

long long nCr(int x, int y) {
    return (f[x] * inv[y] % mod * inv[x - y] % mod) % mod;
}

long long power(long long base, long long exp, long long mod) {
    long long result = 1;
    while (exp > 0) {
        if (exp % 2 == 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp /= 2;
    }
    return result;
}

int main() {
