    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<long long> dp1(n + 2), dp2(n + 2);
        dp1[0] = 1;
        for (int i = 0; i < n; ++i) {
            int x;
            cin >> x;
            dp1[x + 1] = (dp1[x + 1] << 1) % mod;
            dp1[x + 1] = (dp1[x + 1] + dp1[x]) % mod;
            if (x > 0) {
                dp2[x - 1] = (dp2[x - 1] << 1) % mod;
                dp2[x - 1] = (dp2[x - 1] + dp1[x - 1]) % mod;
            }
            dp2[x + 1] = (dp2[x + 1] << 1) % mod;
        }
        long long ans = 0;
        for (int i = 0; i <= n + 1; ++i) {
            ans = (ans + dp1[i] + dp2[i]) % mod;
        }
        cout << (ans - 1 + mod) % mod << '\n';
    }
