const int BUFSIZE = 8192;

class FastIO {
public:
    char buffer[BUFSIZE];
    int pos;
    bool eof;

    FastIO() : pos(0), eof(false) {}

    void read(char* s, int n) {
        while (n > 0 && !eof) {
            if (pos == BUFSIZE) {
                pos = 0;
                cin.read(buffer, BUFSIZE);
                if (cin.gcount() < BUFSIZE)
                    eof = true;
            }
            int to_read = min(n, BUFSIZE - pos);
            memcpy(s, buffer + pos, to_read);
            s += to_read;
            n -= to_read;
        }
    }

    void write(const char* s, int n) {
        cout.write(s, n);
    }

    string readline() {
        string line;
        while (true) {
            read(buffer, BUFSIZE);
            int i = 0;
            for (; buffer[i] != '\n' && buffer[i] != '\0'; ++i)
                line += buffer[i];
            if (buffer[i] == '\n') {
                ++i;
                break;
            }
        }
        return line;
    }

    void flush() {
        cout.flush();
    }
};

