#include <iostream>
#include <vector>
#include <string>

void solve() {
    int n, k, x;
    std::cin >> n >> k >> x;
    std::string s;
    std::cin >> s;

    if (s.find('*') == std::string::npos) {
        std::cout << s << std::endl;
        return;
    }

    std::vector<std::string> stars;
    std::istringstream iss(s);
    std::string token;
    while (std::getline(iss, token, 'a')) {
        if (!token.empty()) {
            stars.push_back(token);
        }
    }

    // A string of q stars can expand to 0, 1, 2, ..., q * k b's, which is
    // 1 + k * q possibilities
    std::vector<int> expand;
    for (const auto& star : stars) {
        expand.push_back(1 + k * star.length());
    }

    // Cumulative product of number of stars
    std::vector<int> prods;
    prods.push_back(expand.back());
    for (int i = 1; i < stars.size(); ++i) {
        prods.push_back(prods.back() * expand[stars.size() - i - 1]);
    }

    --x;

    // Count how many b's to replace each * by
    std::vector<int> counts;
    for (int i = prods.size() - 1; i >= 0; --i) {
        counts.push_back(x / prods[i]);
        x -= prods[i] * (x / prods[i]);
    }
    counts.push_back(x % prods[0]);

    // Construct the string
    std::string answer;
    int i = 1;
    size_t j = 0;
    while (j < s.length()) {
        if (s[j] == 'a') {
            answer += 'a';
            ++j;
        } else {
            answer.append(counts[i], 'b');
            ++i;
            while (j < s.length() && s[j] == '*') {
                ++j;
            }
        }
    }

    std::cout << answer << std::endl;
}

int main() {
    int t;
    std::cin >> t;
    for (int i = 0; i < t; ++i) {
        solve();
    }
    return 0;
}

