using namespace std;

vector<int> process(const vector<int>& A, const vector<int>& B, const vector<vector<int>>& Q) {
    vector<int> S = {0};
    int n = A.size();
    for (int i = 0; i < n; ++i) {
        int ai = A[i];
        int bi = B[i];
        int di = bi - ai;
        S.push_back(S.back() + di);
    }
    n = S.size();
    int p = ceil(log2(n));
    p = pow(2, p);
    vector<int> min_tree(2 * p - 1, INT_MAX);
    vector<int> max_tree(2 * p - 1, -INT_MAX);
    for (int i = 0; i < p; ++i) {
        if (i < n) {
            min_tree[i] = S[i];
            max_tree[i] = S[i];
        }
    }
    for (int i = p; i < 2 * p - 1; ++i) {
        int i1 = (2 * p - 2) - i;
        int j1 = 2 * i1 + 1;
        int j2 = 2 * i1 + 2;
        int i_left = (2 * p - 2) - j1;
        int i_right = (2 * p - 2) - j2;
        min_tree[i] = min(min_tree[i_left], min_tree[i_right]);
        max_tree[i] = max(max_tree[i_left], max_tree[i_right]);
    }
    auto find_max = [&](int l, int r, int start_l = 0, int start_r = p - 1, int start_i = 2 * p - 2) {
        if (start_i < 0)
            return INT_MIN;
        if (l == r)
            return max_tree[l];
        if (l == start_l && r == start_r)
            return max_tree[start_i];
        int m1 = (start_l + start_r) / 2;
        if (l > m1)
            return find_max(l, r, m1 + 1, start_r, i_r);
        else if (r <= m1)
            return find_max(l, r, start_l, m1, i_l);
        else {
            int max1 = find_max(l, m1, start_l, m1, i_l);
            int max2 = find_max(m1 + 1, r, m1 + 1, start_r, i_r);
            return max(max1, max2);
        }
    };
    auto find_min = [&](int l, int r, int start_l = 0, int start_r = p - 1, int start_i = 2 * p - 2) {
        if (start_i < 0)
            return INT_MAX;
        if (l == r)
            return min_tree[l];
        if (l == start_l && r == start_r)
            return min_tree[start_i];
        int m1 = (start_l + start_r) / 2;
        if (l > m1)
            return find_min(l, r, m1 + 1, start_r, i_r);
        else if (r <= m1)
            return find_min(l, r, start_l, m1, i_l);
        else {
            int min1 = find_min(l, m1, start_l, m1, i_l);
            int min2 = find_min(m1 + 1, r, m1 + 1, start_r, i_r);
            return min(min1, min2);
        }
    };
    vector<int> answer;
    for (const auto& qr : Q) {
        int l = qr[0] - 1;
        int r = qr[1];
        int s1 = S[l];
        int s2 = S[r];
        if (s1 != s2)
            answer.push_back(-1);
        else {
            int my_min = find_min(l, r);
            int my_max = find_max(l, r);
            if (my_min - s1 < 0)
                answer.push_back(-1);
            else
                answer.push_back(my_max - s1);
        }
    }
    return answer;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    vector<int> A(n), B(n);
    for (int i = 0; i < n; ++i)
        cin >> A[i];
    for (int i = 0; i < n; ++i)
        cin >> B[i];
    vector<vector<int>> Q(k);
    for (int i = 0; i < k; ++i) {
        int l, r;
        cin >> l >> r;
        Q[i] = {l, r};
    }

    vector<int> answer = process(A, B, Q);
    for (int x : answer)
        cout << x << '\n';

    return 0;
}

