class Dsu {
public:
    vector<int> parent;

    Dsu(int n) : parent(n + 1, 0) {}

    void makeSet() {
        for (int i = 1; i <= n; ++i) {
            parent[i] = i;
        }
    }

    int findParent(int node) {
        if (node == parent[node]) {
            return node;
        }
        return parent[node] = findParent(parent[node]);
    }

    int unionSets(int u, int v) {
        int u_parent = findParent(u);
        int v_parent = findParent(v);

        if (u_parent != v_parent) {
            parent[v_parent] = u_parent;
            return -1;
        }
        return 0;
    }

    void checkComponent(int u, int v) {
        if (findParent(u) != findParent(v)) {
            cout << "Both belongs to different components" << endl;
        } else {
            cout << "same component" << endl;
        }
    }

    void reUnion(int u, int v) {}

private:
    int n = 0;
};

