const int MOD = 998244353;

std::array<int, 3> egcd(int a, int b) {
    if (a == 0)
        return {b, 0, 1};
    else {
        auto [g, y, x] = egcd(b % a, a);
        return {g, x - (b / a) * y, y};
    }
}

int modinv(int a, int m) {
    auto [g, x, y] = egcd(a, m);
    if (g != 1)
        throw std::runtime_error("modular inverse does not exist");
    else
        return (x % m + m) % m;
}

int choose(int n, int k, int p) {
    if (k == 0)
        return 1;
    long long x = n;
    for (long long y = n - 1; y > n - k; --y) {
        x = x * y % p;
    }
    long long d = 1;
    for (int i = 2; i <= k; ++i) {
        d = d * i % p;
    }
    return static_cast<int>((x * modinv(d, p)) % p);
}

