class FastIO {
public:
    char *buffer;
    size_t buffer_size, pos;
    FILE *file;

    FastIO(FILE *f) : file(f), buffer(new char[BUFSIZE]), buffer_size(BUFSIZE), pos(0) {}

    ~FastIO() { delete[] buffer; }

    void read() {
        while (true) {
            size_t bytes_read = fread(buffer, 1, BUFSIZE, file);
            if (bytes_read == 0)
                break;
            pos += bytes_read;
        }
    }

    string readline() {
        string line;
        char ch;
        while ((ch = fgetc(file)) != '\n' && ch != EOF) {
            line += ch;
        }
        return line;
    }

    void write(const string &s) {
        fwrite(s.c_str(), 1, s.size(), file);
    }
};

