                buffer.seek(toFileOffset: ptr)
            } else {
                break
            }
        }
        newlines = 0
        return String(buffer)
    }

    func readline() -> String {
        while newlines == 0 {
            if let data = buffer.readData(ofLength: BUFSIZE), !data.isEmpty {
                newlines = (String(data, encoding: .ascii) ?? "").components(separatedBy: "\n").count - 1
                ptr = buffer.offset
                buffer.seekToEndOfFile()
                buffer.write(data)
                buffer.seek(toFileOffset: ptr)
            } else {
                break
            }
        }
        newlines -= 1
        return String(buffer.split(separator: "\n")[0], encoding: .ascii) ?? ""
    }

    func flush() {
        if writable {
            FileHandle.standardOutput.write(buffer)
            buffer.truncate(length: 0)
        }
    }
}

class IOWrapper {
    let buffer: FastIO
    var flush: () -> Void
    var writable: Bool
    var write: (String) -> Void
    var read: () -> String
    var readline: () -> String

    init(file: FileHandle) {
        self.buffer = FastIO(file: file)
        self.flush = buffer.flush
        self.writable = buffer.writable
        self.write = { s in buffer.write(s.data(using: .ascii) ?? Data()) }
        self.read = { String(buffer.read(), encoding: .ascii) ?? "" }
        self.readline = { String(buffer.readline(), encoding: .ascii) ?? "" }
    }
}

