func solve() {
    let input = readLine()!.split(separator: " ").map { Int($0)! }
    var n = input[0]
    let k = input[1]
    var x = input[2]
    let s = readLine()!

    if !s.contains("*") {
        print(s)
        return
    }

    let stars = s.split(separator: "a").filter { !$0.isEmpty }

    // A string of q stars can expand to 0, 1, 2, ..., q * k b's, which is
    // 1 + k * q possibilities
    let expand = stars.map { 1 + k * $0.count }

    // Cumulative product of number of stars
    var prods: [Int] = []
    prods.append(expand.last!)
    for i in stride(from: expand.count - 2, through: 0, by: -1) {
        prods.append(prods.last! * expand[i])
    }

    x -= 1

    // Count how many b's to replace each * by
    var counts: [Int] = []
    for prod in prods.reversed() {
        counts.append(x / prod)
        x -= prod * (x / prod)
    }
    counts.append(x % prods[0])

    // Construct the string
    var answer = ""
    var i = 1
    var j = 0
    while j < s.count {
        if s[s.index(s.startIndex, offsetBy: j)] == "a" {
            answer += "a"
            j += 1
        } else {
            let count = counts[i]
            answer += String(repeating: "b", count: count)
            i += 1
            while j < s.count && s[s.index(s.startIndex, offsetBy: j)] == "*" {
                j += 1
            }
        }
    }

    print(answer)
}

