import Foundation

func process(_ A: [Int], _ B: [Int], _ Q: [[Int]]) -> [Int] {
    var S = [0]
    let n = A.count
    for i in 0..<n {
        let ai = A[i]
        let bi = B[i]
        let di = bi - ai
        S.append(S.last! + di)
    }

    let n = S.count
    let p = Int(ceil(log2(Double(n))))
    let p = 1 << p

    var minTree = [Int](repeating: Int.max, count: 2 * p - 1)
    var maxTree = [Int](repeating: Int.min, count: 2 * p - 1)

    for i in 0..<p {
        if i < n {
            minTree[i] = S[i]
            maxTree[i] = S[i]
        }
    }

    for i in p..<2 * p - 1 {
        let i1 = (2 * p - 2) - i
        let j1 = 2 * i1 + 1
        let j2 = 2 * i1 + 2
        let iLeft = (2 * p - 2) - j1
        let iRight = (2 * p - 2) - j2

        minTree[i] = min(minTree[iLeft], minTree[iRight])
        maxTree[i] = max(maxTree[iLeft], maxTree[iRight])
    }

    func findMax(_ l: Int, _ r: Int, _ startL: Int = 0, _ startR: Int = p - 1) -> Int {
        if startL > startR { return Int.min }

        if l == r {
            return maxTree[l]
        }

        let i1 = (2 * p - 2) - startL
        let iLeft = (2 * p - 2) - (2 * i1 + 2)
        let iRight = (2 * p - 2) - (2 * i1 + 1)
        let m1 = (startL + startR) / 2

        if l > m1 {
            return findMax(l, r, startL: m1 + 1, startR: startR)
        } else if r <= m1 {
            return findMax(l, r, startL: startL, startR: m1)
        } else {
            let max1 = findMax(l, m1, startL: startL, startR: m1)
            let max2 = findMax(m1 + 1, r, startL: m1 + 1, startR: startR)
            return max(max1, max2)
        }
    }

    func findMin(_ l: Int, _ r: Int, _ startL: Int = 0, _ startR: Int = p - 1) -> Int {
        if startL > startR { return Int.max }

        if l == r {
            return minTree[l]
        }

        let i1 = (2 * p - 2) - startL
        let iLeft = (2 * p - 2) - (2 * i1 + 2)
        let iRight = (2 * p - 2) - (2 * i1 + 1)
        let m1 = (startL + startR) / 2

        if l > m1 {
            return findMin(l, r, startL: m1 + 1, startR: startR)
        } else if r <= m1 {
            return findMin(l, r, startL: startL, startR: m1)
        } else {
            let min1 = findMin(l, m1, startL: startL, startR: m1)
            let min2 = findMin(m1 + 1, r, startL: m1 + 1, startR: startR)
            return min(min1, min2)
        }
    }

    var answer = [Int]()
    for query in Q {
        let l = query[0] - 1
        let r = query[1]

        let s1 = S[l]
        let s2 = S[r]

        if s1 != s2 {
            answer.append(-1)
        } else {
            let myMin = findMin(l, r)
            let myMax = findMax(l, r)

            if myMin - s1 < 0 {
                answer.append(-1)
            } else {
                answer.append(myMax - s1)
            }
        }
    }

    return answer
}

