class Dsu {
    var parent: [Int]

    init(_ n: Int) {
        self.parent = Array(repeating: 0, count: n + 1)
    }

    func makeSet() {
        for i in 1...n {
            parent[i] = i
        }
    }

    func findParent(_ node: Int) -> Int {
        if node == parent[node] {
            return node
        }
        parent[node] = findParent(parent[node])
        return parent[node]
    }

    func union(_ u: Int, _ v: Int) -> Int {
        let uParent = findParent(u)
        let vParent = findParent(v)

        if uParent != vParent {
            parent[vParent] = uParent
        } else {
            return -1
        }
        return 0
    }

    func checkComponent(_ u: Int, _ v: Int) {
        if findParent(u) != findParent(v) {
            print("Both belongs to different components")
        } else {
            print("same component")
        }
    }

    func reUnion(_ u: Int, _ v: Int) {}
}

