let mod: Int64 = 998244353

func egcd(_ a: Int64, _ b: Int64) -> (Int64, Int64, Int64) {
    if a == 0 {
        return (b, 0, 1)
    } else {
        let (g, y, x) = egcd(b % a, a)
        return (g, x - (b / a) * y, y)
    }
}

func modinv(_ a: Int64, _ m: Int64) -> Int64 {
    let (g, x, _) = egcd(a, m)
    if g != 1 {
        fatalError("modular inverse does not exist")
    } else {
        return (x % m + m) % m
    }
}

func choose(_ n: Int64, _ k: Int64, _ p: Int64) -> Int64 {
    if k == 0 {
        return 1
    }
    var x = n
    for y in stride(from: n-1, through: n-k, by: -1) {
        x = (x * y) % p
    }
    var d = 1
    for i in 2...Int(k) {
        d = (d * Int64(i)) % p
    }
    return (x * modinv(Int64(d), p)) % p
}

func solve() {
    let n = Int(readLine()!)!
    var wb_poss = n > 1
    var bw_poss = n > 1
    var w: Int64 = 0
    var b: Int64 = 0
    var q: Int64 = 0
    var free: Int64 = 0
    var any_bad_poss = n > 1

    for _ in 0..<n {
        let s = readLine()!.trimmingCharacters(in: .whitespacesAndNewlines)
        if s.first == "B" {
            b += 1
            wb_poss = false
        } else if s.first == "W" {
            w += 1
            bw_poss = false
        } else if s.first == "?" {
            q += 1
        }

        if s[s.index(s.startIndex, offsetBy: 1)] == "B" {
            b += 1
            wb_poss = false
        } else if s[s.index(s.startIndex, offsetBy: 1)] == "W" {
            w += 1
            bw_poss = false
        } else if s[s.index(s.startIndex, offsetBy: 1)] == "?" {
            q += 1
        }

        if s.count == 2 && s[0] == s[1], any_bad_poss {
            any_bad_poss = false
        }
    }

    let w_needed = n - w
    if w_needed > q || w_needed < 0 {
        print(0)
        return
    }

    var num_bad_poss: Int64 = 1
    if any_bad_poss {
        num_bad_poss = (pow(Double(free), Double(mod)) % mod).roundedToInt64()
        num_bad_poss -= bw_poss ? 1 : 0 + wb_poss ? 1 : 0
    }

    let result = (choose(q, w_needed, mod) - num_bad_poss + mod) % mod
    print(result)
}

