    var index = 0

    func read() -> String {
        while index < buffer.count {
            let endIndex = buffer.firstIndex(of: 0) ?? buffer.endIndex
            if endIndex > index {
                return String(bytes: buffer[index..<endIndex], encoding: .ascii)!
            }
            buffer.removeSubrange(0..<index)
            index = 0
        }
        return ""
    }

    func readLine() -> String {
        while true {
            let endIndex = buffer.firstIndex(of: 10) ?? buffer.endIndex
            if endIndex > index {
                let line = String(bytes: buffer[index..<endIndex], encoding: .ascii)!
                buffer.removeSubrange(0..<endIndex)
                index = 0
                return line.trimmingCharacters(in: .whitespacesAndNewlines)
            }
            buffer.removeSubrange(0..<index)
            index = 0
        }
    }

    func write(_ string: String) {
        buffer.append(string.data(using: .ascii)!)
