def mpow(a, b=mod - 2, m=mod):
    res = 1
    a %= m
    assert b >= 0
    while b:
        if b & 1:
            res = (res * a) % m
        a = (a * a) % m
        b >>= 1
    return res

def init():
    fac[2:] = [(fac[i - 1] * i) % mod for i in range(2, sz)]
    ifac[-1] = mpow(fac[-1])
    for i in range(sz - 2, 0, -1):
        ifac[i] = (ifac[i + 1] * (i + 1)) % mod
    for i in range(2, int(math.sqrt(sz))):
        if prime[i] != i:
            continue
        for j in range(i * i, sz, i):
            if prime[j] == j:
                prime[j] = i

