function pw(x: number, k: number): number {
  let res: number = 1;
  while (k) {
    if (k & 1) {
      res *= x;
      res %= mod;
    }
    k >>= 1;
    x *= x;
    x %= mod;
  }
  return res;
}

function c(n: number, k: number): number {
  if (k < 0) return 0;
  let res: number = 1;
  for (let i: number = n - k + 1; i < n + 1; ++i) {
    res *= i;
    res %= mod;
  }
  for (let i: number = 2; i < k + 1; ++i) {
    res *= pw(i, mod - 2);
    res %= mod;
  }
  return res;
}

