func dfs(v int) {
	if color[v] {
		return
	}
	color[v] = true
	if a[v] == 0 {
		dp[v] = 0
		color[v] = false
		return
	}
	u := f[v]
	if !color[u] {
		dfs(u)
	}
	if color[u] {
