func log2(x int) int {
	return 31 - bits.LeadingZeros(uint(x))
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n, q int
	fmt.Fscanf(scanner, "%d %d\n", &n, &q)

	a := make([]int64, n)
	for i := range a {
		fmt.Fscanf(scanner, "%d\n", &a[i])
	}

	for i := range a {
		var b int
		fmt.Fscanf(scanner, "%d\n", &b)
		a[i] = int64(b) - a[i]
		if i > 0 {
			a[i] += a[i-1]
		}
	}

	mn := make([][]int64, 20)
	mx := make([][]int64, 20)
	for i := range mn {
		mn[i] = make([]int64, n)
		mx[i] = make([]int64, n)
	}
	copy(mn[0], a)
	copy(mx[0], a)

	for k := 1; k < 20; k++ {
		for i := range mn[k] {
			if i+(1<<(k-1)) < n {
				mn[k][i] = min(mn[k-1][i], mn[k-1][i+(1<<(k-1))])
				mx[k][i] = max(mx[k-1][i], mx[k-1][i+(1<<(k-1))])
			}
		}
	}

	for q > 0 {
		q--
		var l, r int
		fmt.Fscanf(scanner, "%d %d\n", &l, &r)
		l--

		k := log2(r - l)
		minVal := min(mn[k][l], mn[k][r-(1<<k)])
		maxVal := max(mx[k][l], mx[k][r-(1<<k)])

		start := int64(0)
		if l > 0 {
			start = a[l-1]
		}

		if start != a[r-1] || minVal < start {
			fmt.Fprintln(writer, "-1")
		} else {
			fmt.Fprintf(writer, "%d\n", maxVal-start)
		}
	}
}

