var beg [2]int

func dfs(x, y, t int) int {
	fmt.Printf("dfs %d %d %d\n", x, y, t)
	if x < 0 || x == n || y < 0 || y == m {
		return 0
	}
	if vis[x][y] && ret[x][y] < cur {
		cyc = true
		beg[0], beg[1] = x, y
		return ans[x][y] = t - fusnfe[x][y]
	}
	if vis[x][y] {
		return ans[x][y]
	}
	vis[x][y] = true
	fusnfe[x][y] = t
	var gox, goy int
	switch str[x][y] {
	case 'R':
		goy++
	case 'L':
		goy--
	case 'U':
		gox--
	case 'D':
		gox++
	}
	r := dfs(gox, goy, t+1)
	if cyc {
		if x == beg[0] && y == beg[1] {
			cyc = false
		}
		ans[x][y] = r
	} else {
		ans[x][y] = r + 1
	}
	fmt.Printf("ans %d %d = %d cyc %v\n", x, y, ans[x][y], cyc)
	ret[x][y] = cur
	return ans[x][y]
}

