func mpow(a, b, m int64) int64 {
	res := int64(1)
	a %= m
	for b > 0 {
		if b&1 == 1 {
			res = res * a % m
		}
		a = a * a % m
		b >>= 1
	}
	return res
}

func init() {
	fac = make([]int64, sz)
	ifac = make([]int64, sz)
	fac[0] = 1
	for i := int64(2); i < sz; i++ {
		fac[i] = fac[i-1] * i % mod
	}
	ifac[sz-1] = mpow(fac[sz-1], mod-2, mod)
	for i := sz - 2; i >= 0; i-- {
		ifac[i] = ifac[i+1] * (i + 1) % mod
	}
	prime = make([]int, sz)
	for i := range prime {
		prime[i] = i
	}
	for i := int64(2); i*i < sz; i++ {
		if prime[i] != int(i) {
			continue
		}
		for j := i * i; j < sz; j += i {
			if prime[j] == int(j) {
				prime[j] = int(i)
			}
		}
	}
}

func nCr(n, r int64) int64 {
	if n <= 0 || r < 0 {
		return 0
	}
	if n < r {
		return 0
	}
	return (fac[n] * (ifac[r] * ifac[n-r] % mod)) % mod
}

func gcd(a, b int64) int64 {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

func lcm(a, b int64) int64 {
	return (a / gcd(a, b)) * b
}

