public class Main {
    private static final double EPS = 0.000001;
    private static final int MOD = 998244353;
    private static final int INF = 1000000101;
    private static final long LLINF = 1223372000000000555L;
    private static final int N = (int) 2e6 + (int) 3e2;
    private static final int M = 522;

    private static int[] a = new int[N];
    private static int[] f = new int[N];
    private static int[] dp = new int[N];
    private static int[] color = new int[N];
    private static boolean cycle = false;

    private static void dfs(int v) {
        if (cycle) return;
        color[v] = 1;
        if (a[v] == 0) {
            dp[v] = 0;
            color[v] = 2;
            return;
        }
        int u = f[v];
        if (color[u] == 0) dfs(u);
        if (color[u] == 1) {
            cycle = true;
            return;
        }
        dp[v] = dp[u] + 1;
        color[v] = 2;
    }

    private static void solve(int TC) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(System.out));
        String[] line = reader.readLine().split(" ");
        int n = Integer.parseInt(line[0]);
        int d = Integer.parseInt(line[1]);
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(reader.readLine());
            f[i] = (i + n - d) % n;
            color[i] = 0;
            dp[i] = INF;
        }
        cycle = false;
        for (int i = 0; i < n; i++) {
            if (color[i] == 0) dfs(i);
            if (cycle) break;
        }
        if (cycle) {
            writer.write("-1\n");
            return;
        }
        int maxDP = Arrays.stream(dp).max().getAsInt();
        writer.write(maxDP + "\n");
    }

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(System.out));
        String[] line = reader.readLine().split(" ");
        int TC = Integer.parseInt(line[0]);
        for (int test = 1; test <= TC; test++) {
            solve(test);
        }
        writer.close();
    }
}

