        if (x < 0 || x == n || y < 0 || y == m) return 0;
        if (vis[x][y] == cur && ret[x][y] < cur) {
            cyc = 1;
            return ans[x][y] = fusnfe[x][y];
        }
        if (vis[x][y] == cur) return ans[x][y];
        vis[x][y] = cur;
        fusnfe[x][y] = x * m + y;
        int gox = x, goy = y;
        if (str[x][y] == 'R') goy++;
        if (str[x][y] == 'L') goy--;
        if (str[x][y] == 'U') gox--;
        if (str[x][y] == 'D') gox++;
        int r = dfs(gox, goy);
        if (cyc != 0) {
            ans[x][y] = r;
        } else
            ans[x][y] = r + 1;
        ret[x][y] = cur;
        return ans[x][y];
    }

