import java.util.Scanner;

public class Main {
    private static final int maxn = (int) 1e5 + 7, inf = (int) 2e9 + 9, mod = 998244353;
    private static char[] a = new char[2];

    public static long pw(long x, int k) {
        long res = 1L;
        while (k > 0) {
            if ((k & 1) == 1) {
                res *= x;
                res %= mod;
            }
            k >>= 1;
            x *= x;
            x %= mod;
        }
        return res;
    }

    public static long c(int n, int k) {
        if (k < 0) return 0;
        long res = 1;
        for (int i = n - k + 1; i < n + 1; ++i) {
            res *= i;
            res %= mod;
        }
        for (int i = 2; i < k + 1; ++i) {
            res *= pw(i, mod - 2);
            res %= mod;
        }
        return res;
    }

    public static boolean is(char[] c) {
        return a[0] == c[0] && a[1] == c[1];
    }

    public static void solve() {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int _b = 0, b_ = 0, _w = 0, w_ = 0, __ = 0, e = 0, tw = 0, tb = 0;
        boolean same = false;
        for (int i = 0; i < n; ++i) {
            a = scanner.next().toCharArray();
            for (int j = 0; j < 2; ++j) {
                if (a[j] == 'B')
                    tb++;
                else if (a[j] == 'W')
                    tw++;
            }
            if (is(new char[]{'?', '?'})) __++;
            if (is(new char[]{'B', 'B'}) || is(new char[]{'W', 'W'})) same = true;
            switch (a[0]) {
                case 'B':
                    b_ = true;
                    break;
                case 'W':
                    w_ = true;
                    break;
                case '?':
                    e++;
                    break;
            }
            switch (a[1]) {
                case 'B':
                    _b = true;
                    break;
                case 'W':
                    _w = true;
                    break;
                case '?':
                    e++;
                    break;
            }
        }
        int d = Math.abs(tb - tw);
        long res = c(e, (e - d) / 2);
        if (!same) {
            res -= pw(2, __);
            if (!_w && !b_) res += mod; // Ensure non-negative result
            if (!w_ && !_b) res += mod; // Ensure non-negative result
            res = (res + mod) % mod;
        }
        System.out.println(res);
    }

    public static void main(String[] args) {
        solve();
    }
}

