import java.util.*;

public class Main {
    private static final long MOD = 998244353;
    private static final int SZ = (int) 2e6 + 5;
    private static List<Long> fac = new ArrayList<>(Collections.nCopies(SZ, 1L));
    private static List<Long> ifac = new ArrayList<>(Collections.nCopies(SZ, 0L));
    private static List<Integer> prime = new ArrayList<>(Collections.nCopies(SZ, 0));

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = scanner.nextInt();
        init();
        for (int i = 1; i <= t; i++) {
            solve(scanner);
        }
    }

    private static long mpow(long a, long b, long m) {
        long res = 1;
        a %= m;
        assert b >= 0;
        for (; b > 0; b >>= 1) {
            if ((b & 1) == 1) res = (res * a) % m;
            a = (a * a) % m;
        }
        return res;
    }

    private static void init() {
        fac.set(0, 1L);
        for (int i = 2; i < SZ; i++) {
            fac.set(i, (fac.get(i - 1) * i) % MOD);
        }
        ifac.set(SZ - 1, mpow(fac.get(SZ - 1), MOD - 2, MOD));
        for (int i = SZ - 2; i >= 0; i--) {
            ifac.set(i, (ifac.get(i + 1) * (i + 1)) % MOD);
        }
        prime.set(0, 0);
        prime.set(1, 0);
        for (int i = 2; i < SZ; i++) {
            prime.set(i, i);
        }
        for (int i = 2; i * i < SZ; i++) {
            if (prime.get(i) != i) continue;
            for (int j = i * i; j < SZ; j += i) {
                if (prime.get(j) == j) prime.set(j, i);
            }
        }
    }

    private static long nCr(long n, long r) {
        if (n <= 0 || r < 0) return 0;
        if (n < r) return 0;
        return ((fac.get((int) n) * (ifac.get((int) r) * ifac.get((int) (n - r)) % MOD)) % MOD);
    }

    private static long gcd(long a, long b) {
        return (b == 0) ? a : gcd(b, a % b);
    }

    private static long lcm(long a, long b) {
        return ((a / gcd(a, b)) * b);
    }

    private static void solve(Scanner scanner) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int k = scanner.nextInt();
        int highTables = n % m;
        int remTables = m - highTables;
        int highPeople = (n + m - 1) / m;
        int lessPeople = n / m;
        Queue<Integer> players = new LinkedList<>();
        for (int i = 1; i <= n; i++) {
            players.add(i);
        }
        for (int game = 0; game < k; game++) {
            for (int tableNo = 1; tableNo <= highTables; ++tableNo) {
