class Program
{
    private static Random rng = new Random();
    private const double eps = 1e-6;
    private const int MOD = 998244353;
    private const int INF = 1000000101;
    private const long LLINF = 1223372000000000555;
    private const int N = (int)(2e6 + 3e2);
    private const int M = 522;

    private static int[] a = new int[N];
    private static int[] f = new int[N];
    private static int[] dp = new int[N];
    private static int[] color = new int[N];
    private static bool cycle = false;

    private static void Dfs(int v)
    {
        if (cycle) return;
        color[v] = 1;
        if (a[v] == 0)
        {
            dp[v] = 0;
            color[v] = 2;
            return;
        }
        int u = f[v];
        if (color[u] == 0) Dfs(u);
        if (color[u] == 1)
        {
            cycle = true;
            return;
        }
        dp[v] = dp[u] + 1;
        color[v] = 2;
    }

    private static void Solve(int TC)
    {
        string[] inputLines = Console.ReadLine().Split(' ');
        int n = int.Parse(inputLines[0]);
        int d = int.Parse(inputLines[1]);

        for (int i = 0; i < n; i++)
        {
            a[i] = int.Parse(Console.ReadLine());
            f[i] = (i + n - d) % n;
            color[i] = 0;
            dp[i] = INF;
        }

        cycle = false;
        for (int i = 0; i < n; i++)
        {
            if (color[i] == 0) Dfs(i);
            if (cycle) break;
        }

        if (cycle)
        {
            Console.WriteLine(-1);
            return;
        }

        Console.WriteLine(dp.Max());
    }

    public static void Main(string[] args)
    {
        int TC = int.Parse(Console.ReadLine());
        for (int test = 1; test <= TC; test++)
        {
            Solve(test);
        }
    }
