class Program
{
    static int Log2(int x) => 31 - BitOperations.LeadingZeroCount(x);

    static void Main()
    {
        Console.SetIn(new System.IO.StreamReader(Console.OpenStandardInput()));
        Console.SetOut(new System.IO.StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false });

        int n, q;
        var input = Console.ReadLine().Split();
        n = int.Parse(input[0]);
        q = int.Parse(input[1]);

        long[] a = new long[n];
        for (int i = 0; i < n; i++)
        {
            a[i] = long.Parse(Console.ReadLine());
        }

        for (int i = 0; i < n; i++)
        {
            int b = int.Parse(Console.ReadLine());
            a[i] = b - a[i];
            if (i > 0)
            {
                a[i] += a[i - 1];
            }
        }

        long[][] mn = new long[20][];
        long[][] mx = new long[20][];
        for (int i = 0; i < 20; i++)
        {
            mn[i] = new long[n];
            mx[i] = new long[n];
        }

        Array.Copy(a, mn[0], n);
        Array.Copy(a, mx[0], n);

        for (int k = 1; k < 20; k++)
        {
            for (int i = 0; i + (1 << (k - 1)) < n; i++)
            {
                mn[k][i] = Math.Min(mn[k - 1][i], mn[k - 1][i + (1 << (k - 1))]);
                mx[k][i] = Math.Max(mx[k - 1][i], mx[k - 1][i + (1 << (k - 1))]);
            }
        }

        while (q-- > 0)
        {
            var query = Console.ReadLine().Split();
            int l = int.Parse(query[0]) - 1;
            int r = int.Parse(query[1]) - 1;

            int k = Log2(r - l);
            long _min = Math.Min(mn[k][l], mn[k][r - (1 << k)]);
            long _max = Math.Max(mx[k][l], mx[k][r - (1 << k)]);

            long start = l > 0 ? a[l - 1] : 0;
            if (start != a[r - 1] || _min < start)
            {
                Console.WriteLine("-1");
            }
            else
            {
                Console.WriteLine(_max - start);
            }
        }

        Console.Out.Flush();
    }
}

