        long res = 1;
        for (int i = n - k + 1; i < n + 1; ++i)
        {
            res *= i;
            res %= mod;
        }
        for (int i = 2; i < k + 1; ++i)
        {
            res *= pw(i, mod - 2);
            res %= mod;
        }
        return res;
    }

    static bool Is(string c) => a[0] == c[0] && a[1] == c[1];

    static void Solve()
    {
