using System.Collections.Generic;

class Program
{
    const long mod = 998244353;
    const long sz = 2_000_005;
    static List<long> fac = new List<long>(new long[sz]);
    static List<long> ifac = new List<long>(new long[sz]);
    static List<int> prime = new List<int>(new int[sz]);

    static long mpow(long a, long b = mod - 2, long m = mod)
    {
        long res = 1;
        a %= m;
        for (; b > 0; b >>= 1)
        {
            if ((b & 1) == 1) res = (res * a) % m;
            a = (a * a) % m;
        }
        return res;
    }

    static void init()
    {
        fac[0] = 1;
        for (long i = 1; i < sz; i++) fac[i] = (fac[i - 1] * i) % mod;
        ifac[sz - 1] = mpow(fac[sz - 1]);
        for (long i = sz - 2; i >= 0; i--)
            ifac[i] = (ifac[i + 1] * (i + 1)) % mod;

        prime[0] = 0;
        prime[1] = 0;
        for (int i = 2; i < sz; i++) prime[i] = i;
        for (long i = 2; i * i < sz; i++)
        {
            if (prime[i] != i) continue;
            for (long j = i * i; j < sz; j += i)
                if (prime[j] == j) prime[j] = i;
        }
    }

    static long nCr(long n, long r)
    {
        if (n <= 0 || r < 0) return 0;
        if (n < r) return 0;
        return ((fac[n] * (ifac[r] * ifac[n - r]) % mod)) % mod;
    }

    static long gcd(long a, long b)
    {
        while (b != 0)
        {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    static long lcm(long a, long b)
    {
        return (a / gcd(a, b)) * b;
    }

    static void solve()
    {
        string[] input = Console.ReadLine().Split(' ');
        long n = long.Parse(input[0]);
        long m = long.Parse(input[1]);
        long k = long.Parse(input[2]);

        long highTables = n % m;
        long remTables = m - highTables;
        long highPeople = (n + m - 1) / m;
        long lessPeople = n / m;

        Queue<long> players = new Queue<long>();
        for (int i = 1; i <= n; i++) players.Enqueue(i);

        for (long game = 0; game < k; game++)
        {
            for (long tableNo = 1; tableNo <= highTables; ++tableNo)
            {
                Console.Write(highPeople + " ");
                for (int peep = 1; peep <= highPeople; peep++)
                {
                    long indx = players.Dequeue();
                    Console.Write(indx + " ");
                    players.Enqueue(indx);
                }
                Console.WriteLine();
            }

            for (long tableNo = 1; tableNo <= remTables; ++tableNo)
            {
                Console.Write(lessPeople + " ");
                for (int peep = 1; peep <= lessPeople; peep++)
                {
                    long indx = players.Dequeue();
                    Console.Write(indx + " ");
                    players.Enqueue(indx);
                }
                Console.WriteLine();
            }

            long shiftBack = highTables * highPeople;
            for (int i = 0; i < shiftBack; i++)
            {
                long indx = players.Dequeue();
                players.Enqueue(indx);
            }
        }

        Console.WriteLine();
    }

    static void Main()
    {
        init();

        int t = 1;
        string[] input = Console.ReadLine().Split(' ');
        t = int.Parse(input[0]);

        for (int i = 1; i <= t; i++)
        {
            solve();
        }
    }
}

