fn power(x: u64, y: u64, mod_val: u64) -> u64 {
    let mut ans = 1;
    let mut x = x % mod_val;
    let mut y = y;
    while y > 0 {
        if y % 2 == 1 {
            ans = (ans * x) % mod_val;
        }
        y /= 2;
        x = (x * x) % mod_val;
    }
    ans
}

