fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut input_iter = input.split_whitespace();

    fn solve(input: &mut dyn Iterator<Item = &str>) -> String {
        let n: usize = input.next().unwrap().parse().unwrap();
        let d: usize = input.next().unwrap().parse().unwrap();
        let a: Vec<usize> = (0..n).map(|_| input.next().unwrap().parse().unwrap()).collect();
        let f: Vec<usize> = (0..n).map(|i| (i + n - d) % n).collect();
        let mut color = vec![0; n];
        let mut dp = vec![usize::MAX; n];
        let mut cycle = false;

        fn dfs(v: usize, a: &Vec<usize>, f: &Vec<usize>, color: &mut Vec<u8>, dp: &mut Vec<usize>, cycle: &mut bool) {
            if *cycle { return; }
            color[v] = 1;
            if a[v] == 0 {
                dp[v] = 0;
                color[v] = 2;
                return;
            }
            let u = f[v];
            if color[u] == 0 { dfs(u, a, f, color, dp, cycle); }
            if color[u] == 1 {
                *cycle = true;
                return;
            }
            dp[v] = dp[u] + 1;
            color[v] = 2;
        }

        for i in 0..n {
            if color[i] == 0 { dfs(i, &a, &f, &mut color, &mut dp, &mut cycle); }
            if cycle { break; }
        }

        if cycle {
            "-1".to_string()
        } else {
            dp.iter().cloned().max().unwrap().to_string()
        }
    }

    let mut TC: usize = input_iter.next().unwrap().parse().unwrap();
    let mut output = vec![];
    for test in 1..=TC {
        output.push(solve(&mut input_iter));
    }

    for line in output {
        println!("{}", line);
    }
}

