fn log2(x: usize) -> usize {
    31 - x.leading_zeros() as usize
}

fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input)?;
    let mut input = input.trim().split_whitespace();

    let n = input.next().unwrap().parse()?;
    let q = input.next().unwrap().parse()?;

    let mut a: Vec<i64> = vec![0; n as usize];
    for i in 0..n {
        let b1: i64 = input.next().unwrap().parse()?;
        let b2: i64 = input.next().unwrap().parse()?;
        a[i as usize] = b1 - b2;
        if i > 0 {
            a[i as usize] += a[(i - 1) as usize];
        }
    }

    let mut mn: Vec<Vec<i64>> = vec![vec![0; n as usize]; 20];
    let mut mx: Vec<Vec<i64>> = vec![vec![0; n as usize]; 20];

    for i in 0..n {
        mn[0][i as usize] = a[i as usize];
        mx[0][i as usize] = a[i as usize];
    }

    for k in 1..20 {
        for i in 0..(n - (1 << (k - 1))) {
            mn[k][i as usize] = mn[k - 1][i as usize].min(mn[k - 1][(i + (1 << (k - 1))) as usize]);
            mx[k][i as usize] = mx[k - 1][i as usize].max(mx[k - 1][(i + (1 << (k - 1))) as usize]);
        }
    }

    for _ in 0..q {
