        let r: usize = input.next().unwrap().parse()?;

        let k = log2(r - l);
        let min_val = mn[k][l].min(mn[k][(r - (1 << k))]);
        let max_val = mx[k][l].max(mx[k][(r - (1 << k))]);

        let start = if l > 0 { a[l - 1] } else { 0 };
        if start != a[r - 1] || min_val < start {
            println!("-1");
        } else {
            println!("{}", max_val - start);
        }
    }

    Ok(())
}

