fn dfs(x: usize, y: usize, t: usize, str: &Vec<Vec<char>>, vis: &mut Vec<Vec<usize>>, ret: &mut Vec<Vec<usize>>, fusnfe: &mut Vec<Vec<usize>>, ans: &mut Vec<Vec<usize>>, cur: usize) -> usize {
    println!("dfs {} {} {}", x, y, t);
    if x == 0 || x > str.len() - 1 || y == 0 || y > str[0].len() - 1 {
        return 0;
    }
    if vis[x][y] == cur && ret[x][y] < cur {
        let beg = (x, y);
        let mut cyc = true;
        ans[x][y] = t - fusnfe[x][y];
        cyc = false;
        return ans[x][y];
    }
    if vis[x][y] == cur {
        return ans[x][y];
    }
    vis[x][y] = cur;
    fusnfe[x][y] = t;
    let (mut gox, mut goy) = (x, y);
    match str[x - 1][y - 1] {
        'R' => goy += 1,
        'L' => goy -= 1,
        'U' => gox -= 1,
        'D' => gox += 1,
        _ => {}
    }
    let r = dfs(gox, goy, t + 1, str, vis, ret, fusnfe, ans, cur);
    if cyc {
        if (x, y) == beg {
            cyc = false;
        }
        ans[x][y] = r;
    } else {
        ans[x][y] = r + 1;
    }
    println!("ans {} {} = {} cyc {}", x, y, ans[x][y], cyc);
    ret[x][y] = cur;
    return ans[x][y];
}

