fn pw(x: i64, k: u32) -> i64 {
    let mut res = 1;
    let mut x = x;
    let mut k = k;
    while k > 0 {
        if k & 1 == 1 {
            res *= x;
            res %= MOD;
        }
        k >>= 1;
        x *= x;
        x %= MOD;
    }
    res
}

fn c(n: i32, k: i32) -> i64 {
    if k < 0 {
        return 0;
    }
    let mut res = 1;
    for i in (n - k + 1)..(n + 1) {
        res *= i as i64;
        res %= MOD;
    }
    for i in 2..=k {
        res *= pw(i as i64, MOD as u32 - 2);
        res %= MOD;
    }
    res
}

fn is(c: &[u8; 2]) -> bool {
    a[0] == c[0] && a[1] == c[1]
}

