fn solve() {
    let mut input = String::new();
    io::stdin().read_line(&mut input).unwrap();
    let n: i32 = input.trim().parse().unwrap();

    let mut _b = 0;
    let mut b_ = false;
    let mut _w = 0;
    let mut w_ = false;
    let mut __ = 0;
    let mut e = 0;
    let mut tw = 0;
    let mut tb = 0;
    let mut same = false;

    for _ in 0..n {
        input.clear();
        io::stdin().read_line(&mut input).unwrap();
        unsafe { a.copy_from_slice(input.trim().as_bytes()) };

        if is(b"??") {
            __ += 1;
        }
        if is(b"BB".as_bytes()) || is(b"WW".as_bytes()) {
            same = true;
        }

        match a[0] {
            b'B' => b_ = true,
            b'W' => w_ = true,
            b'?' => e += 1,
            _ => {}
        }
        match a[1] {
            b'B' => _b += 1,
            b'W' => _w += 1,
            b'?' => e += 1,
            _ => {}
        }

        tb += if a[0] == b'B' { 1 } else { 0 };
        tw += if a[1] == b'W' { 1 } else { 0 };
    }

    let d = (tb - tw).abs();
    let mut res = c(e, (e - d) / 2);

    if !same {
        res -= pw(2, __ as u32);
        if !_w && !b_ {
            res += 1;
        }
        if !w_ && !_b {
            res += 1;
        }
        res = (res + MOD) % MOD;
    }

    print!("{}", res);
}

