fn solve(u: usize, n: usize, x: &[i32], y: &[i32]) -> i64 {
    let mut cnt = [0; 4];
    for i in 1..=n {
        if i == u { continue; }
        let _x = (x[i] - x[u]).abs();
        let _y = (y[i] - y[u]).abs();
        let id = if _x & 1 != 0 { 2 } else { 0 } + if _y & 1 != 0 { 1 } else { 0 };
        cnt[id] += 1;
    }
    let mut sum = 0;
    sum += (cnt[0] * cnt[1]) as i64 + (cnt[0] * cnt[2]) as i64 + (cnt[0] * cnt[3]) as i64;
    for &c in cnt.iter() {
        sum += (c * (c - 1)) / 2;
    }
    sum
}

