use std::collections::VecDeque;
use std::io::{self, Write};

const MOD: u64 = 998244353;
const SZ: usize = 2_000_005;

fn mpow(a: u64, b: u64, m: u64) -> u64 {
    let mut res = 1;
    let mut a = a % m;
    assert!(b >= 0);
    for _ in 0..b {
        if b & 1 == 1 {
            res = (res * a) % m;
        }
        a = (a * a) % m;
    }
    res
}

fn init() -> (Vec<u64>, Vec<u64>, Vec<usize>) {
    let mut fac = vec![1; SZ];
    let mut ifac = vec![0; SZ];
    for i in 2..SZ {
        fac[i] = (fac[i - 1] * i as u64) % MOD;
    }
    ifac[SZ - 1] = mpow(fac[SZ - 1], MOD - 2, MOD);
    for i in (0..SZ - 2).rev() {
        ifac[i] = (ifac[i + 1] * (i as u64 + 1)) % MOD;
    }
    let mut prime = vec![i for i in 0..SZ];
    for i in 2..(SZ as f64).sqrt() as usize {
        if prime[i] != i {
            continue;
        }
        for j in (i * i..SZ).step_by(i) {
            if prime[j] == j {
                prime[j] = i;
            }
        }
    }
    (fac, ifac, prime)
}

fn nCr(n: u64, r: u64) -> u64 {
    if n <= 0 || r < 0 {
        return 0;
    }
    if n < r {
        return 0;
    }
    (fac[n as usize] * ((ifac[r as usize] * ifac[(n - r) as usize]) % MOD)) % MOD
}

fn gcd(a: u64, b: u64) -> u64 {
    if b == 0 {
        a
    } else {
        gcd(b, a % b)
    }
}

fn lcm(a: u64, b: u64) -> u64 {
    (a / gcd(a, b)) * b
}

