    let high_tables = n % m;
    let rem_tables = m - high_tables;
    let high_people = (n + m - 1) / m;
    let less_people = n / m;

    let mut players: VecDeque<u64> = (1..=n).collect();
    for _ in 0..k {
        for table_no in 1..=high_tables {
