func power(_ x: Int, _ y: Int, _ MOD: Int) -> Int {
    var ans = 1
    var x = x % MOD
    var y = y
    while y > 0 {
        if y % 2 == 1 { ans = (ans * x) % MOD }
        y /= 2
        x = (x * x) % MOD
    }
    return ans
}

