func pw(_ x: Int, _ k: Int) -> Int {
    var res = 1
    var k = k
    var x = x
    while k > 0 {
        if k & 1 == 1 {
            res *= x
            res %= mod
        }
        k >>= 1
        x *= x
        x %= mod
    }
    return res
}

func c(_ n: Int, _ k: Int) -> Int {
    guard k >= 0 else { return 0 }
    var res = 1
    for i in (n - k + 1)...(n) {
        res *= i
        res %= mod
    }
    for i in 2...k {
        res *= pw(i, mod - 2)
        res %= mod
    }
    return res
}

