var ifac: [Int64] = Array(repeating: 1, count: sz)
var prime: [Int] = Array(repeating: 0, count: sz)

func mpow(_ a: Int64, _ b: Int64 = mod - 2, _ m: Int64 = mod) -> Int64 {
    var res = Int64(1)
    var a = a % m
    assert(b >= 0)
    for i in stride(from: 0, through: b, by: 1) where (b & 1) != 0 {
        res = res * a % m
    }
    for i in stride(from: 0, through: b / 2, by: 1) {
        a = a * a % m
    }
    return res
}

func initFunc() {
    fac[0] = 1
    ifac[sz - 1] = mpow(fac[sz - 1])
    for i in 2..<sz {
        fac[i] = (fac[i - 1] * Int64(i)) % mod
        ifac[i] = (ifac[i - 1] * Int64(i)) % mod
    }
    prime[0] = 0
    prime[1] = 0
    for i in 2..<sz {
        prime[i] = i
    }
    for i in stride(from: 2, through: Int(sqrt(Double(sz))) + 1, by: 1) {
        if prime[i] != i { continue }
        for j in stride(from: i * i, through: sz - 1, by: i) {
            if prime[j] == j { prime[j] = i }
        }
    }
}

func nCr(_ n: Int64, _ r: Int64) -> Int64 {
    if n <= 0 || r < 0 { return 0 }
    if n < r { return 0 }
    return (fac[Int(n)] * (ifac[Int(r)] * ifac[Int(n - r)] % mod)) % mod
}

