const INF = Math.floor(Number.MAX_SAFE_INTEGER / 2);

function main() {
    const readline = require('readline');
    const rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout
    });

    let T: number;
    let N: number;
    let D: number;
    let arr: number[];
    let dist: number[];
    let q: ArrayDeque<number>;
    let res: number;
    let sb = '';

    rl.on('line', (input) => {
        if (!T) {
            T = parseInt(input.trim());
        } else if (!N) {
            [N, D] = input.split(' ').map(Number);
            arr = readArr(N);
            dist = new Array(N).fill(INF);
            q = new ArrayDeque<number>();
            for (let i = 0; i < N; i++) {
                if (arr[i] === 0) {
                    dist[i] = 0;
                    q.add(i);
                }
            }
        } else {
            while (q.size() > 0) {
                const curr = q.poll();
                let next = (curr + D) % N;
                if (dist[next] === INF) {
                    dist[next] = dist[curr] + 1;
                    q.add(next);
                }
            }
            res = Math.max(...dist) || -1;
            sb += `${res}\n`;
        }

        T--;
        if (T === 0) {
            console.log(sb);
            rl.close();
        }
    });
}

function readArr(N: number): number[] {
    return new Promise<number[]>((resolve) => {
        const readline = require('readline');
        const rl = readline.createInterface({
            input: process.stdin,
            output: process.stdout
        });

        rl.on('line', (input) => {
            arr = input.split('').map(Number);
            resolve(arr);
        });
    });
}

class ArrayDeque<T> {
    private items: T[] = [];

    add(item: T): void {
        this.items.push(item);
    }

    poll(): T | undefined {
        return this.items.shift();
    }

    size(): number {
        return this.items.length;
    }
}

