class CF1556E {
    private tmax: number[];
    private tmin: number[];
    private aa: number[];
    private n: number;

    constructor() {
        this.tmax = [];
        this.tmin = [];
        this.aa = [];
        this.n = 0;
    }

    private build(): void {
        for (let i = 0; i < this.n; i++) {
            this.tmax[this.n + i] = this.tmin[this.n + i] = this.aa[i];
        }
        for (let i = this.n - 1; i > 0; i--) {
            this.tmax[i] = Math.max(this.tmax[i << 1], this.tmax[i << 1 | 1]);
            this.tmin[i] = Math.min(this.tmin[i << 1], this.tmin[i << 1 | 1]);
        }
    }

    private qmax(l: number, r: number): number {
        let ans = -Infinity;
        for (l += this.n, r += this.n; l <= r; l >>= 1, r >>= 1) {
            if ((l & 1) == 1) {
                ans = Math.max(ans, this.tmax[l++]);
            }
            if ((r & 1) == 0) {
                ans = Math.max(ans, this.tmax[r--]);
            }
        }
        return ans;
    }

    private qmin(l: number, r: number): number {
        let ans = Infinity;
        for (l += this.n, r += this.n; l <= r; l >>= 1, r >>= 1) {
            if ((l & 1) == 1) {
                ans = Math.min(ans, this.tmin[l++]);
            }
            if ((r & 1) == 0) {
                ans = Math.min(ans, this.tmin[r--]);
            }
        }
        return ans;
    }

