            for (let i = 0; i < this.n; i++) {
                this.aa[i] += parseInt(lines[3 + i]);
            }
            for (let i = 1; i < this.n; i++) {
                this.aa[i] += this.aa[i - 1];
            }
            this.build();
            let index = 4 + this.n;
            while (q-- > 0) {
                const l = parseInt(lines[index++]) - 1;
                const r = parseInt(lines[index++]) - 1;
                const a = l == 0 ? 0 : this.aa[l - 1];
