class FastIOAdapter {
    private input: string[] = [];
    private index: number = 0;

    constructor() {
        const lines = readLineSync().split('\n');
        this.input = lines.map(line => line.split(' ').map(s => s.trim()));
    }

    next(): string {
        return this.input[this.index++].shift()!;
    }

    nextInt(): number {
        return parseInt(this.next(), 10);
    }
}

function solve(io: FastIOAdapter): void {
    const n = io.nextInt();
    const m = io.nextInt();
    const a: string[][] = [];
    for (let i = 0; i < n; i++) {
        a[i] = io.next().split('');
    }

    const lengths: number[][] = Array.from({ length: n }, () => Array(m).fill(0));
    const indices: number[][] = Array.from({ length: n }, () => Array(m).fill(0));

    let x = 0, y = 0;
    let max = 0;

    for (let i = 0; i < n; i++) {
        for (let j = 0; j < m; j++) {
            if (lengths[i][j] === 0) { // we did not check this
                const stack: [number, number][] = [];
                stack.push([i, j]);
                lengths[i][j] = -1; // we were here
                indices[i][j] = 0;
                let length = 1;
                let cycle = 0;
                let cycX = -1, cycY = -1;

                while (true) {
                    const [xc, yc] = stack[stack.length - 1];
                    if (a[xc][yc] === 'U') xc--;
                    else if (a[xc][yc] === 'D') xc++;
                    else if (a[xc][yc] === 'L') yc--;
                    else yc++;

                    if (xc < 0 || xc >= n || yc < 0 || yc >= m) break;
                    else if (lengths[xc][yc] < 0) {
                        cycle -= indices[xc][yc] - 1;
                        length = cycle + 1;
                        cycX = xc;
                        cycY = yc;
                        break;
                    } else if (lengths[xc][yc] > 0) {
                        length = lengths[xc][yc] + 1;
                        break;
                    } else {
                        lengths[xc][yc] = -1;
                        indices[xc][yc] = ++cycle;
                        stack.push([xc, yc]);
                    }
                }

                const isCycle = cycX !== -1;
                let len = isCycle ? cycle : length;

                while (stack.length > 0) {
                    const [xy] = stack.pop()!;
                    lengths[xy[0]][xy[1]] = len;
                    if (isCycle) {
                        if (xy[0] === cycX && xy[1] === cycY) {
                            isCycle = false;
                            len = length;
                        }
                    } else len++;
                }

                if (max < lengths[i][j]) {
                    max = lengths[i][j];
                    x = i + 1;
                    y = j + 1;
                }
            }
        }
    }

    console.log(`${x} ${y} ${max}`);
}

