let cDiana: number[] = [];
let cMocha: number[] = [];

let visD: boolean[] = [];
let visM: boolean[] = [];

function dfs1(i: number, marker: number): void {
  visM[i] = true;
  cMocha[i] = marker;

  for (const e of mocha[i]) {
    if (!visM[e]) {
      dfs1(e, marker);
    }
  }
}

function dfs2(i: number, marker: number): void {
  visD[i] = true;
  cDiana[i] = marker;

  for (const e of diana[i]) {
    if (!visD[e]) {
      dfs2(e, marker);
    }
  }
}

function marker1(n: number): number {
  let count = 1;
  for (let i = 1; i <= n; ++i) {
    if (!visM[i]) {
      dfs1(i, count);
      ++count;
    }
  }
  return count - 1;
}

function marker2(n: number): number {
  let count = 1;
  for (let i = 1; i <= n; ++i) {
    if (!visD[i]) {
      dfs2(i, count);
      ++count;
    }
  }
  return count - 1;
}

