  visM = Array(n + 1).fill(false);

  for (let i = 1; i <= n; ++i) {
    cMocha[i] = i;
    cDiana[i] = i;
  }

  for (let i = 0; i < m1; ++i) {
    const [u, v] = input.slice(3 + 2 * i, 5 + 2 * i).map(Number);
