class FastScanner {
    private br: string;
    private st: string[];

    constructor() {
        this.br = readFileSync(0, 'utf8');
        this.st = [];
    }

    next(): string {
        while (this.st.length === 0) {
            const data = this.br.split(/\s+/).filter(Boolean);
            this.st = data.slice(1);
            this.br = '';
        }
        return this.st.shift()!;
    }

    nextInt(): number {
        return parseInt(this.next(), 10);
    }

    readArray(n: number): number[] {
        const a: number[] = [];
        for (let i = 0; i < n; i++) {
            a.push(this.nextInt());
        }
        return a;
    }

    nextLong(): number {
        return parseInt(this.next(), 10);
    }
}

function gcd(a: number, b: number): number {
