const mod = 998244353;

function binPow(a: number, b: number): number {
    let res = 1;
    while (b > 0) {
        a = a % mod;
        if ((b & 1) === 1) {
            res = (res * a) % mod;
        }
        b >>= 1;
        a = (a * a) % mod;
    }
    return res;
}

function modInverse(a: number): number {
    return binPow(a, mod - 2);
}

function mul(a: number, b: number): number {
    return (a * b) % mod;
}

function nCr(n: number, r: number): number {
    let res = mul(fact[n], invFact[r]);
    res = mul(res, invFact[n - r]);
    return res;
}

let fact: number[] = [];
let invFact: number[] = [];

rl.question('', (nStr) => {
    const n = parseInt(nStr);
    const ls: string[] = [];
    let full = false;
    let black = 0, white = 0;

    for (let i = 0; i < n; ++i) {
        rl.question('', (line) => {
            ls.push(line);
            if (line.charAt(0) === 'W') white++;
            if (line.charAt(0) === 'B') black++;
            if (line.charAt(1) === 'W') white++;
            if (line.charAt(1) === 'B') black++;
            if (line.charAt(0) !== '?' && line.charAt(0) === line.charAt(1)) {
                full = true;
            }

            if (i === n - 1) {
                if (black > n || white > n) {
                    console.log(0);
                    rl.close();
                    return;
                }

                fact[0] = 1;
                invFact[0] = 1;
                for (let i = 1; i <= 2 * n; ++i) {
                    fact[i] = mul(fact[i - 1], i);
                    invFact[i] = modInverse(fact[i]);
                }

                const empty = 2 * n - black - white;
                let ans = nCr(empty, n - black);

                if (full) {
                    console.log(ans);
                    rl.close();
                    return;
                }

                let invalid = 1;
                let WB = true, BW = true;

                for (let i = 0; i < n; ++i) {
                    if (ls[i].charAt(0) === '?' && ls[i].charAt(1) === '?') {
                        invalid = mul(invalid, 2);
                    }
                    if (ls[i].charAt(0) === 'B' || ls[i].charAt(1) === 'W') {
                        WB = false;
                    }
                    if (ls[i].charAt(0) === 'W' || ls[i].charAt(1) === 'B') {
                        BW = false;
                    }
                }

                if (WB) invalid--;
                if (BW) invalid--;

                ans = (ans - invalid + mod) % mod;
                console.log(ans);
                rl.close();
            }
        });
    }
});

