const mod = 998244353

func dc(a int64) int {
	r := 0
	for a > 0 {
		r++
		a /= 10
	}
	return r
}

func gcd(a, b int) int {
	if b == 0 {
		return a
	}
	return gcd(b, a%b)
}

func gcdInt64(a, b int64) int64 {
	if b == 0 {
		return a
	}
	return gcdInt64(b, a%b)
}

func mp(a, p int64) int64 {
	r := int64(1)
	for p > 0 {
		if (p & 1) == 1 {
			r = (r * a) % mod
		}
		p >>= 1
		a = (a * a) % mod
	}
	return r
}

func solve() {
	scanner := bufio.NewScanner(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	for scanner.Scan() {
		tc, _ := strconv.Atoi(scanner.Text())
		for tc > 0 {
			n, _ := strconv.Atoi(scanner.Text())
			A := make([]int, n)
			for i := range A {
				A[i], _ = strconv.Atoi(scanner.Text())
			}

			D := make([][]int64, n+1)
			for i := range D {
				D[i] = make([]int64, 3)
			}

			for i := n - 1; i >= 0; i-- {
				u := A[i]
				var zero int64
				if u+1 <= n {
					zero += D[u+1][0]
				}
				if u+2 <= n {
					zero += D[u+2][1]
				}
				var one int64
				if u > 1 {
					one += D[u-2][2]
				}
				var two int64
				if u+2 <= n {
					two += D[u+2][1]
				}

				D[u][0] = (D[u][0] + zero) % mod
				D[u][1] = (D[u][1] + one) % mod
				D[u][2] = (D[u][2] + two) % mod
			}

			ans := (D[0][0] + D[1][1]) % mod
			fmt.Fprintln(writer, ans)
			tc--
		}
	}
}

