				}
				reverse(a, in1)
				if in1 > in2 {
					in2 = in1 - in2
				}
				reverse(a, in2-1)
				reverse(a, in2+1)
				reverse(a, 2)
				reverse(a, i-1)
				list = append(list, in1+1, in2, in2+2, 3, i)
			}
			fmt.Fprintf(writer, "%d\n", len(list))
