func solve(io *FastIOAdapter) {
	n := io.nextInt()
	m := io.nextInt()
	a := make([][]byte, n)
	for i := 0; i < n; i++ {
		a[i] = []byte(io.next())
	}
	lengths := make([][]int, n)
	indices := make([][]int, n)
	for i := range lengths {
		lengths[i] = make([]int, m)
		indices[i] = make([]int, m)
	}
	var x, y, max int
	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			if lengths[i][j] == 0 { // we did not check this
				stack := [][]int{{i, j}}
				lengths[i][j] = -1 // we were here
				indices[i][j] = 0
				var length int = 1
				var cycle int = 0
				var cycX, cycY int = -1, -1
				for {
					xy := stack[len(stack)-1]
					xc, yc := xy[0], xy[1]
					if a[xc][yc] == 'U' {
						xc--
					} else if a[xc][yc] == 'D' {
						xc++
					} else if a[xc][yc] == 'L' {
						yc--
					} else {
						yc++
					}
					if xc < 0 || xc >= n || yc < 0 || yc >= m {
						break
					} else if lengths[xc][yc] < 0 {
						cycle -= indices[xc][yc] - 1
						length = cycle + 1
						cycX, cycY = xc, yc
						break
					} else if lengths[xc][yc] > 0 {
						length = lengths[xc][yc] + 1
						break
					} else {
						lengths[xc][yc] = -1
						indices[xc][yc] = cycle + 1
						stack = append(stack, []int{xc, yc})
					}
				}
				isCycle := cycX != -1
				var len int
				if isCycle {
					len = cycle
				} else {
					len = length
				}
				for len > 0 {
					xy := stack[len-1]
					lengths[xy[0]][xy[1]] = len
					if isCycle && xy[0] == cycX && xy[1] == cycY {
						isCycle = false
						len = length
					} else {
						len--
					}
				}
				if max < lengths[i][j] {
					max = lengths[i][j]
					x, y = i+1, j+1
				}
			}
		}
	}
	io.out.Println(x, y, max)
}

func main() {
	count := 1
	for count > 0 {
		solve(&FastIOAdapter{})
		count--
	}
}

