const mod = 998244353

var fact, invFact []int64

// Fermat's Little Theorem:
// (a^p - a) % p = 0
// => a^p % p - a % p = 0
// => a^p % p = a % p
// => a^(p - 1) % p = (a * a^-1) % p
// => a^(p - 1) % p = 1 % p
// => a^(p - 2) % p = a^-1 % p

func binPow(a, b int64) int64 {
	res := int64(1)
	for b > 0 {
		a %= mod
		if b&1 == 1 {
			res = (res * a) % mod
		}
		b >>= 1
		a = (a * a) % mod
	}
	return res
}

func modInverse(a int64) int64 {
	return binPow(a, mod-2)
}

func mul(a, b int64) int64 {
	return (a * b) % mod
}

func nCr(n, r int) int64 {
	res := mul(fact[n], invFact[r])
	res = mul(res, invFact[n-r])
	return res
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	n := 0
	fmt.Fscanf(scanner, "%d\n", &n)
	ls := make([]string, n)
	var full bool
	black, white := 0, 0

	for i := 0; i < n; i++ {
		scanner.Scan()
		ls[i] = scanner.Text()
		if ls[i][0] == 'W' {
			white++
		}
		if ls[i][0] == 'B' {
			black++
		}
		if ls[i][1] == 'W' {
			white++
		}
		if ls[i][1] == 'B' {
			black++
		}
		if ls[i][0] != '?' && ls[i][0] == ls[i][1] {
			full = true
		}
	}

	if black > n || white > n {
		fmt.Fprintln(writer, 0)
		return
	}

	fact = make([]int64, 2*n+1)
	invFact = make([]int64, 2*n+1)
	fact[0] = 1
	invFact[0] = 1
	for i := int64(1); i <= int64(2*n); i++ {
		fact[i] = mul(fact[i-1], i)
		invFact[i] = modInverse(fact[i])
	}

	empty := 2*n - black - white
	ans := nCr(empty, n-black)

	if full {
		fmt.Fprintln(writer, ans)
		return
	}

	invalid := int64(1)
