func newFastScanner() *fastScanner {
	return &fastScanner{
		scanner: bufio.NewScanner(os.Stdin),
		buffer:  make([]byte, 0),
	}
}

type fastScanner struct {
	scanner *bufio.Scanner
	buffer  []byte
}

func (fs *fastScanner) next() string {
	for fs.scanner.Scan() {
		fs.buffer = append(fs.buffer, fs.scanner.Bytes()...)
		break
	}
	return strings.TrimSpace(string(fs.buffer))
}

func (fs *fastScanner) nextInt() int {
	i, _ := strconv.Atoi(strings.TrimSpace(string(fs.buffer)))
	fs.buffer = nil
	return i
}

