public class Program
{
    private static readonly long mod = 998244353;

    public static void Main()
    {
        var reader = new StreamReader(Console.OpenStandardInput());
        var writer = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = true };

        int tc = int.Parse(reader.ReadLine());
        while (tc-- > 0)
        {
            int n = int.Parse(reader.ReadLine());
            var A = Array.ConvertAll(reader.ReadLine().Split(), int.Parse);

            long[,] D = new long[n + 1, 3];

            for (int i = n - 1; i >= 0; i--)
            {
                int u = A[i];
                long zero = 1L + D[u, 0];
                if (u + 1 <= n) zero += D[u + 1, 0];
                if (u + 2 <= n) zero += D[u + 2, 1];
                long one = 1L + D[u, 1];
                if (u > 1) one += D[u - 2, 2];
                long two = 1L + D[u, 2];
                if (u + 2 <= n) two += D[u + 2, 1];

                D[u, 0] = (D[u, 0] + zero) % mod;
                D[u, 1] = (D[u, 1] + one) % mod;
                D[u, 2] = (D[u, 2] + two) % mod;
            }

            long ans = (D[0, 0] + D[1, 1]) % mod;
            writer.WriteLine(ans);
        }

        writer.Flush();
    }

    private static int dc(long a)
    {
        int r = 0;
        while (a > 0)
        {
            r++;
            a /= 10;
        }
        return r;
    }

    private static int gcd(int a, int b) => b == 0 ? a : gcd(b, a % b);
    private static long gcd(long a, long b) => b == 0 ? a : gcd(b, a % b);
    private static long mp(long a, long p)
    {
        long r = 1;
        while (p > 0)
        {
            if ((p & 1) == 1) r = (r * a) % mod;
            p >>= 1;
            a = (a * a) % mod;
        }
        return r;
    }
}

