class Program
{
    const int INF = int.MaxValue / 2;

    static void Main()
    {
        string[] inputLines = Console.ReadLine().Split(' ');
        int T = int.Parse(inputLines[0]);
        StringBuilder sb = new StringBuilder();
        while (T-- > 0)
        {
            inputLines = Console.ReadLine().Split(' ');
            int N = int.Parse(inputLines[0]);
            int D = int.Parse(inputLines[1]);
            int[] arr = ReadArr(N, Console.ReadLine());
            int[] dist = new int[N];
            Array.Fill(dist, INF);
            Queue<int> q = new Queue<int>();
            for (int i = 0; i < N; i++)
                if (arr[i] == 0)
                {
                    dist[i] = 0;
                    q.Enqueue(i);
                }
            while (q.Count > 0)
            {
                int curr = q.Dequeue();
                int next = (curr + D) % N;
                if (dist[next] == INF)
                {
                    dist[next] = dist[curr] + 1;
                    q.Enqueue(next);
                }
            }
            int res = 0;
            foreach (int x in dist)
                res = Math.Max(res, x);
            if (res == INF)
                res = -1;
            sb.Append(res + "\n");
        }
        Console.Write(sb.ToString());
    }

    static int[] ReadArr(int N, string inputLine)
    {
        int[] arr = new int[N];
        string[] tokens = inputLine.Split(' ');
        for (int i = 0; i < N; i++)
            arr[i] = tokens[i][0] - '0';
        return arr;
    }
}

