    public static void Solve(int n, int k, long x, string s)
    {
        StringBuilder res = new StringBuilder();
        x--;
        for (int i = n - 1; i >= 0; i--)
        {
            if (s[i] == 'a')
            {
                res.Append('a');
            }
            else
            {
                int count = 1;
                while (i - count >= 0 && s[i] == s[i - count]) count++;
                long baseValue = (count * k) + 1;
                for (long j = 0; j < x % baseValue; j++)
                    res.Append('b');
                x = x / baseValue;
                i = i - count + 1;
            }
        }
        Console.WriteLine(new string(res.ToString().Reverse().ToArray()));
    }

