using System;

public class CF1556E
{
    private static readonly long INF = 0x3f3f3f3f3f3f3f3fL;
    private long[] aa, tmax, tmin;
    private int n;

    public void Build()
    {
        tmax = new long[n * 2];
        tmin = new long[n * 2];
        for (int i = 0; i < n; i++)
            tmax[n + i] = tmin[n + i] = aa[i];
        for (int i = n - 1; i > 0; i--)
        {
            tmax[i] = Math.Max(tmax[i << 1], tmax[i << 1 | 1]);
            tmin[i] = Math.Min(tmin[i << 1], tmin[i << 1 | 1]);
        }
    }

    public long QMax(int l, int r)
    {
        long ans = -INF;
        for (l += n, r += n; l <= r; l >>= 1, r >>= 1)
        {
            if ((l & 1) == 1)
                ans = Math.Max(ans, tmax[l++]);
            if ((r & 1) == 0)
                ans = Math.Max(ans, tmax[r--]);
        }
        return ans;
    }

    public long QMin(int l, int r)
    {
        long ans = INF;
        for (l += n, r += n; l <= r; l >>= 1, r >>= 1)
        {
            if ((l & 1) == 1)
                ans = Math.Min(ans, tmin[l++]);
            if ((r & 1) == 0)
                ans = Math.Min(ans, tmin[r--]);
        }
        return ans;
    }

    public void Main()
    {
        string[] input = Console.ReadLine().Split();
        n = int.Parse(input[0]);
        int q = int.Parse(input[1]);

        aa = new long[n];
        for (int i = 0; i < n; i++)
