using System;
using System.Collections.Generic;
using System.IO;

public class Codeforces_753_E2
{
    private static void Solve(FastIOAdapter io)
    {
        int n = io.NextInt();
        int m = io.NextInt();
        char[,] a = new char[n, m];
        for (int i = 0; i < n; i++)
        {
            string line = io.ReadLine();
            for (int j = 0; j < m; j++)
            {
                a[i, j] = line[j];
            }
        }

        int[,] lengths = new int[n, m];
        int[,] indices = new int[n, m];
        int x = 0, y = 0;
        int max = 0;

        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < m; j++)
            {
                if (lengths[i, j] == 0) // we did not check this
                {
                    Stack<int[]> stack = new Stack<int[]>();
                    stack.Push(new int[] { i, j });
                    lengths[i, j] = -1; // we were here
                    indices[i, j] = 0;
                    int length = 1;
                    int cycle = 0;
                    int cycX = -1, cycY = -1;

                    while (true)
                    {
                        int[] xy = stack.Peek();
                        int xc = xy[0], yc = xy[1];
                        if (a[xc, yc] == 'U') { xc--; }
                        else if (a[xc, yc] == 'D') { xc++; }
                        else if (a[xc, yc] == 'L') { yc--; }
                        else { yc++; }

                        if (xc < 0 || xc >= n || yc < 0 || yc >= m) { break; }
                        else if (lengths[xc, yc] < 0)
                        {
                            cycle -= indices[xc, yc] - 1;
                            length = cycle + 1;
                            cycX = xc;
                            cycY = yc;
                            break;
                        }
                        else if (lengths[xc, yc] > 0)
                        {
                            length = lengths[xc, yc] + 1;
                            break;
                        }
                        else
                        {
                            lengths[xc, yc] = -1;
                            indices[xc, yc] = ++cycle;
                            stack.Push(new int[] { xc, yc });
                        }
                    }

                    bool isCycle = cycX != -1;
                    int len = isCycle ? cycle : length;

                    while (stack.Count > 0)
                    {
                        int[] xy = stack.Pop();
                        lengths[xy[0], xy[1]] = len;
                        if (isCycle)
                        {
                            if (xy[0] == cycX && xy[1] == cycY)
                            {
                                isCycle = false;
                                len = length;
                            }
                        }
                        else { len++; }
                    }

                    if (max < lengths[i, j])
                    {
                        max = lengths[i, j];
                        x = i + 1;
                        y = j + 1;
                    }
                }
            }
        }

        io.Out.WriteLine($"{x} {y} {max}");
    }

    public static void Main(string[] args)
    {
        using (FastIOAdapter ioAdapter = new FastIOAdapter())
        {
            int count = 1;
            count = ioAdapter.NextInt();
            while (count-- > 0)
            {
                Solve(ioAdapter);
            }
        }
    }

    static void RuffleSort(int[] arr)
    {
        int n = arr.Length;
        Random rnd = new Random();
        for (int i = 0; i < n; ++i)
        {
            int tmp = arr[i];
            int randomPos = i + rnd.Next(n - i);
            arr[i] = arr[randomPos];
            arr[randomPos] = tmp;
        }
        Array.Sort(arr);
    }

    static class FastIOAdapter : IDisposable
    {
        private readonly StreamReader _reader;
        public StreamWriter Out { get; }

        public FastIOAdapter()
        {
            _reader = new StreamReader(Console.OpenStandardInput());
            Out = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = true };
        }

        public string Next() => _reader.ReadLine();
        public int NextInt() => int.Parse(_reader.ReadLine());
        public long NextLong() => long.Parse(_reader.ReadLine());

        public void Dispose()
        {
            _reader.Dispose();
            Out.Dispose();
        }
    }
