        }
        long res = 0L;
        for (int centerr = 0; centerr < N; centerr++)
        {
            Point c = arr[centerr];
            long[, ,] freq = new long[2, 2, 2];
            for (int i = centerr + 1; i < N; i++)
                if (i != centerr)
                {
                    Point p = arr[i];
                    int t1 = 1;
                    if (p.x % 2 != c.x % 2)
                        t1 = 0;
                    if (p.y % 2 != c.y % 2)
                        t1 = 0;
                    int t2 = (p.x & 1);
                    int t3 = (p.y & 1);
                    freq[t1 ^ 1, t2, t3]++;
                }
            long temp = freq[0, 0, 0] * (freq[1, 0, 1] + freq[1, 1, 0] + freq[1, 1, 1]);
            temp += freq[0, 0, 0] * (freq[0, 0, 0] - 1) / 2;
            temp += freq[1, 0, 0] * (freq[1, 0, 0] - 1) / 2;
            temp += freq[0, 0, 1] * (freq[1, 0, 0] + freq[1, 1, 0] + freq[1, 1, 1]);
            temp += freq[0, 0, 1] * (freq[0, 0, 1] - 1) / 2;
            temp += freq[1, 0, 1] * (freq[1, 0, 1] - 1) / 2;
            temp += freq[0, 1, 0] * (freq[1, 0, 0] + freq[1, 0, 1] + freq[1, 1, 1]);
            temp += freq[0, 1, 0] * (freq[0, 1, 0] - 1) / 2;
            temp += freq[1, 1, 0] * (freq[1, 1, 0] - 1) / 2;
            temp += freq[0, 1, 1] * (freq[1, 0, 0] + freq[1, 0, 1] + freq[1, 1, 0]);
            temp += freq[0, 1, 1] * (freq[0, 1, 1] - 1) / 2;
            temp += freq[1, 1, 1] * (freq[1, 1, 1] - 1) / 2;
            res += temp;
        }
        Console.WriteLine(res);
    }

    public static int GCD(int a, int b)
    {
        if (a > b)
            a = (a + b) - (b = a);
        if (a == 0)
            return b;
        return GCD(b % a, a);
    }
