const INF: i32 = i32::MAX / 2;

fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input)?;
    let mut lines = input.lines();

    let T: usize = lines.next().unwrap().parse()?;
    let mut output = String::new();

    for _ in 0..T {
        let line = lines.next().unwrap();
        let mut st = line.split_whitespace();
        let N: usize = st.next().unwrap().parse()?;
        let D: usize = st.next().unwrap().parse()?;

        let arr: Vec<i32> = read_arr(N, &mut lines);
        let dist = bfs(N, D, &arr);

        if dist == INF {
            output.push_str("-1\n");
        } else {
            output.push_str(&format!("{}\n", dist));
        }
    }

    io::stdout().write_all(output.as_bytes())?;
    Ok(())
}

fn read_arr(_N: usize, lines: &mut std::str::Lines) -> Vec<i32> {
    let line = lines.next().unwrap();
    line.chars()
        .map(|c| c.to_digit(10).unwrap() as i32)
        .collect()
}

fn bfs(N: usize, D: usize, arr: &Vec<i32>) -> i32 {
    let mut dist = vec![INF; N];
    let mut q = VecDeque::new();

    for (i, &val) in arr.iter().enumerate() {
        if val == 0 {
            dist[i] = 0;
            q.push_back(i);
        }
    }

    while !q.is_empty() {
        let curr = q.pop_front().unwrap();
        let next = (curr + D) % N;

        if dist[next] == INF {
            dist[next] = dist[curr] + 1;
            q.push_back(next);
        }
    }

    *dist.iter().max().unwrap_or(&-1)
}

