fn solve(n: usize, k: usize, mut x: u64, s: &str) {
    let mut res = String::new();
    x -= 1;
    for i in (0..n).rev() {
        if s.chars().nth(i).unwrap() == 'a' {
            res.push('a');
        } else {
            let mut count = 1;
            while i > 0 && s.chars().nth(i).unwrap() == s.chars().nth(i - 1).unwrap() {
                count += 1;
            }
            let base = (count * k) as u64 + 1;
            for _ in 0..(x % base) {
                res.push('b');
            }
            x /= base;
            i -= count;
        }
    }
    println!("{}", res.chars().rev().collect::<String>());
}

