        for i in 0..n {
            tmax[n + i] = tmin[n + i] = aa[i];
        }
        for i in (1..n).rev() {
            tmax[i] = cmp::max(tmax[i << 1], tmax[i << 1 | 1]);
            tmin[i] = cmp::min(tmin[i << 1], tmin[i << 1 | 1]);
        }

        while q > 0 {
            let l = self.sc.next::<usize>() - 1;
            let r = self.sc.next::<usize>() - 1;
            let a = if l == 0 { 0 } else { aa[l - 1] };
            let b = aa[r];
            if a != b || tmin[l..=r].iter().cloned().min() != Some(a) {
