struct Scanner {
    buf: Vec<u8>,
    pos: usize,
}

impl Scanner {
    fn new() -> Self {
        Scanner {
            buf: vec![0; 1024],
            pos: 0,
        }
    }

    fn next<T>(&mut self) -> T
    where
        T: std::str::FromStr,
        <T as std::str::FromStr>::Err: std::fmt::Debug,
    {
        loop {
            if self.pos >= self.buf.len() {
                self.buf = io::stdin().bytes().map(|b| b.unwrap()).collect();
                self.pos = 0;
            }
            let mut start = self.pos;
            while start < self.buf.len() && !self.buf[start].is_ascii_whitespace() {
                start += 1;
            }
            if start == self.buf.len() {
                continue;
            }
            self.pos = start + 1;
            return std::str::from_utf8(&self.buf[self.pos..start])
                .unwrap()
                .parse()
                .unwrap();
        }
    }
}

