fn solve(io: &mut FastIOAdapter) {
    let n = io.next_int();
    let m = io.next_int();
    let mut a = vec![vec![' '; m]; n];
    for i in 0..n {
        a[i] = io.next().chars().collect();
    }

    let mut lengths = vec![vec![0; m]; n];
    let mut indices = vec![vec![0; m]; n];
    let mut max = 0;
    let mut x = 0;
    let mut y = 0;

    for i in 0..n {
        for j in 0..m {
            if lengths[i][j] == 0 {
                let mut stack: VecDeque<(usize, usize)> = VecDeque::new();
                stack.push_back((i, j));
                lengths[i][j] = -1;
                indices[i][j] = 0;
                let mut length = 1;
                let mut cycle = 0;
                let mut cyc_x = None;
                let mut cyc_y = None;

                while let Some((xc, yc)) = stack.pop_back() {
                    if a[xc][yc] == 'U' {
                        if xc == 0 { break; }
                        stack.push_back((xc - 1, yc));
                        continue;
                    } else if a[xc][yc] == 'D' {
                        if xc == n - 1 { break; }
                        stack.push_back((xc + 1, yc));
                        continue;
                    } else if a[xc][yc] == 'L' {
                        if yc == 0 { break; }
                        stack.push_back((xc, yc - 1));
                        continue;
                    } else {
                        if yc == m - 1 { break; }
                        stack.push_back((xc, yc + 1));
                        continue;
                    }

                    if lengths[xc][yc] < 0 {
                        cycle -= indices[xc][yc] - 1;
                        length = cycle + 1;
                        cyc_x = Some(xc);
                        cyc_y = Some(yc);
                        break;
                    } else if lengths[xc][yc] > 0 {
                        length = lengths[xc][yc] + 1;
                        break;
                    } else {
                        lengths[xc][yc] = -1;
                        indices[xc][yc] = ++cycle;
                        stack.push_back((xc, yc));
                    }
                }

                let is_cycle = cyc_x.is_some();
                let len = if is_cycle { cycle } else { length };

                while let Some((xc, yc)) = stack.pop_back() {
                    lengths[xc][yc] = len;
                    if is_cycle && xc == cyc_x.unwrap() && yc == cyc_y.unwrap() {
                        is_cycle = false;
                        len = length;
                    } else {
                        len += 1;
                    }
                }

                if max < lengths[i][j] {
                    max = lengths[i][j];
                    x = i + 1;
                    y = j + 1;
                }
            }
        }
    }

    writeln!(io.writer, "{} {} {}", x, y, max).unwrap();
}

fn main() -> io::Result<()> {
    let mut io = FastIOAdapter::new();
    let count = io.next_int();
    for _ in 0..count {
        solve(&mut io);
    }
