const MOD: u64 = 998_244_353;

fn bin_pow(mut a: u64, mut b: u64) -> u64 {
    let mut res = 1;
    while b > 0 {
        if b & 1 == 1 {
            res = (res * a) % MOD;
        }
        b >>= 1;
        a = (a * a) % MOD;
    }
    res
}

fn mod_inverse(a: u64) -> u64 {
    bin_pow(a, MOD - 2)
}

fn mul(a: u64, b: u64) -> u64 {
    (a * b) % MOD
}

fn n_cr(n: usize, r: usize) -> u64 {
    let mut res = mul(fact[n], inv_fact[r]);
    res = mul(res, inv_fact[n - r]);
    res
}

fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let n: usize = input.trim().parse()?;
    let mut ls = Vec::with_capacity(n);
    let mut full = false;
    let mut black = 0;
    let mut white = 0;

    for _ in 0..n {
        io::stdin().read_line(&mut input)?;
        let line = input.trim();
        ls.push(line.to_string());
        if line.chars().next().unwrap() == 'W' {
            white += 1;
        }
        if line.chars().next().unwrap() == 'B' {
            black += 1;
        }
        if line.chars().nth(1).unwrap() == 'W' {
            white += 1;
        }
        if line.chars().nth(1).unwrap() == 'B' {
            black += 1;
        }
        if line.chars().next().unwrap() != '?' && line.chars().next().unwrap() == line.chars().nth(1).unwrap() {
            full = true;
        }
    }

    if black > n || white > n {
        println!("0");
        return Ok(());
    }

    let mut fact = vec![0; 2 * n + 1];
    let mut inv_fact = vec![0; 2 * n + 1];
    fact[0] = 1;
    inv_fact[0] = 1;

    for i in 1..=2 * n {
        fact[i] = mul(fact[i - 1], i as u64);
        inv_fact[i] = mod_inverse(fact[i]);
    }

    let empty = 2 * n - black - white;
    let ans = n_cr(empty, n - black);

    if full {
        println!("{}", ans);
        return Ok(());
    }

    let mut invalid = 1;
    let mut wb = true;
    let mut bw = true;

    for line in &ls {
        if line.chars().next().unwrap() == '?' && line.chars().nth(1).unwrap() == '?' {
            invalid = mul(invalid, 2);
        }
        if line.chars().next().unwrap() == 'B' || line.chars().nth(1).unwrap() == 'W' {
            wb = false;
        }
        if line.chars().next().unwrap() == 'W' || line.chars().nth(1).unwrap() == 'B' {
            bw = false;
        }
    }

    if wb {
        invalid -= 1;
    }
    if bw {
        invalid -= 1;
    }

    let ans = ans - invalid;

    println!("{}", ans);

    Ok(())
}

