    let mut points: Vec<Point> = Vec::with_capacity(n);

    for _ in 0..n {
        let line = lines.next().unwrap();
        let parts: Vec<&str> = line.split_whitespace().collect();
        let x: i32 = parts[0].trim().parse().unwrap();
        let y: i32 = parts[1].trim().parse().unwrap();
        points.push(Point { x, y });
    }

    let mut res: i64 = 0;

    for centerr in 0..n {
        let c = &points[centerr];
        let mut freq: HashMap<(i32, i32, i32), i64> = HashMap::new();

        for i in centerr + 1..n {
            if i != centerr {
                let p = &points[i];
                let t1 = if p.x % 2 != c.x % 2 { 0 } else { 1 };
                let t2 = p.x & 1;
                let t3 = p.y & 1;
                *freq.entry((t1, t2, t3)).or_insert(0) += 1;
            }
        }

        for (&(_, _, _), &count) in freq.iter() {
            let temp = count * (freq.get(&(1 - t1, 1 - t2, 1 - t3)).unwrap_or(&0)
                + freq.get(&(1 - t1, 1 - t2, t3)).unwrap_or(&0)
                + freq.get(&(1 - t1, t2, 1 - t3)).unwrap_or(&0));
            res += temp;
        }

        for (&(_, _, _), &count) in freq.iter() {
            let temp = count * (count - 1) / 2;
            res += temp;
        }
    }

    println!("{}", res);
}

