    let out = io::stdout();
    let mut out = io::BufWriter::new(out.lock());

    let n = sc.next_int();
    let m = sc.next_int();
    let k = sc.next_int();

    let b_t = n % m;
    let b_p = n / m + 1;
    let mut next_b = 1;
    let mut next_s = 1;

    if b_t == 0 {
        for _ in 0..k {
            for _ in 0..m {
                write!(out, "{} ", n / m).unwrap();
                for _ in 0..n / m {
                    write!(out, "{} ", next_b).unwrap();
                    next_b = if next_b == n { 1 } else { next_b + 1 };
                }
                writeln!(out).unwrap();
            }
        }
    } else {
        for _ in 0..k {
            for _ in 0..b_t {
                write!(out, "{} ", b_p).unwrap();
