                    write!(out, "{} ", next_b).unwrap();
                    next_b = if next_b == n { 1 } else { next_b + 1 };
                }
                writeln!(out).unwrap();
            }
            next_s = next_b;
            for _ in 0..m - b_t {
                write!(out, "{} ", b_p).unwrap();
                for _ in 0..b_p - 1 {
                    write!(out, "{} ", next_s).unwrap();
                    next_s = if next_s == n { 1 } else { next_s + 1 };
                }
                writeln!(out).unwrap();
            }
        }
    }

