const long mod = 998244353;

class Main {
public:
    void solve() {
        int tc;
        cin >> tc;
        while (tc--) {
            int n;
            cin >> n;
            vector<int> A(n);
            for (int i = 0; i < n; ++i) {
                cin >> A[i];
            }

            vector<vector<long>> D(n + 1, vector<long>(3));
            for (int i = n - 1; i >= 0; --i) {
                int u = A[i];
                long zero = 1L + D[u][0];
                if (u + 1 <= n) zero += D[u + 1][0];
                if (u + 2 <= n) zero += D[u + 2][1];
                long one = 1L + D[u][1];
                if (u > 1) one += D[u - 2][2];
                long two = 1L + D[u][2];
                if (u + 2 <= n) two += D[u + 2][1];

                D[u][0] = (D[u][0] + zero) % mod;
                D[u][1] = (D[u][1] + one) % mod;
                D[u][2] = (D[u][2] + two) % mod;
            }

            long ans = (D[0][0] + D[1][1]) % mod;
            cout << ans << endl;
        }
    }

private:
    int gcd(int a, int b) { return (b == 0 ? a : gcd(b, a % b)); }
    long gcd(long a, long b) { return (b == 0 ? a : gcd(b, a % b)); }
    long mp(long a, long p) {
        long r = 1;
        while (p > 0) {
            if ((p & 1) == 1) r = (r * a) % mod;
            p >>= 1;
            a = (a * a) % mod;
        }
        return r;
    }
};

