void solve(int n, int k, long x, const string& s) {
    string res;
    x--;
    for (int i = n - 1; i >= 0; i--) {
        if (s[i] == 'a') {
            res += 'a';
        } else {
            int count = 1;
            while (i - count >= 0 && s[i] == s[i - count]) count++;
            long base = (count * k) + 1;
            for (long j = 0; j < x % base; j++)
                res += 'b';
            x /= base;
            i -= count + 1;
        }
    }
    reverse(res.begin(), res.end());
    cout << res << endl;
}

