const long INF = 0x3f3f3f3f3f3f3f3fL;

class CF1556E {
public:
    CF1556E() : out(std::cout) {}
    void main() {
        std::cin >> n;
        int q;
        std::cin >> q;
        aa.resize(n);
        for (int i = 0; i < n; i++)
            std::cin >> aa[i];
        for (int i = 1; i < n; i++)
            aa[i] += aa[i - 1];
        build();
        while (q-- > 0) {
            int l, r;
            std::cin >> l >> r;
            l--; r--;
            long a = l == 0 ? 0 : aa[l - 1];
            long b = aa[r];
            out << (a != b || qmin(l, r) != a ? -1 : qmax(l, r) - a) << std::endl;
        }
    }

private:
    std::ostream& out;
    int n;
    std::vector<long> aa, tmax, tmin;

    void build() {
        tmax.resize(n * 2);
        tmin.resize(n * 2);
        for (int i = 0; i < n; i++)
            tmax[n + i] = tmin[n + i] = aa[i];
        for (int i = n - 1; i > 0; i--) {
            tmax[i] = std::max(tmax[i << 1], tmax[i << 1 | 1]);
            tmin[i] = std::min(tmin[i << 1], tmin[i << 1 | 1]);
        }
    }

    long qmax(int l, int r) {
        long ans = -INF;
        for (l += n, r += n; l <= r; l >>= 1, r >>= 1) {
            if ((l & 1) == 1)
                ans = std::max(ans, tmax[l++]);
            if ((r & 1) == 0)
                ans = std::max(ans, tmax[r--]);
        }
        return ans;
    }

    long qmin(int l, int r) {
        long ans = INF;
        for (l += n, r += n; l <= r; l >>= 1, r >>= 1) {
            if ((l & 1) == 1)
                ans = std::min(ans, tmin[l++]);
            if ((r & 1) == 0)
                ans = std::min(ans, tmin[r--]);
        }
        return ans;
    }
};

int main() {
    CF1556E o;
    o.main();
    return 0;
}

#include <iostream>
