#include <stack>
#include <string>
#include <algorithm>

using namespace std;

void solve(istream& in, ostream& out) {
    int n = 0, m = 0;
    in >> n >> m;
    vector<vector<char>> a(n, vector<char>(m));
    for (int i = 0; i < n; ++i) {
        string line;
        in >> line;
        copy(line.begin(), line.end(), a[i].begin());
    }
    vector<vector<int>> lengths(n, vector<int>(m, 0));
    vector<vector<int>> indices(n, vector<int>(m, 0));
    int x = 0, y = 0;
    int max_length = 0;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (lengths[i][j] == 0) { // we did not check this
                stack<pair<int, int>> st;
                st.push({i, j});
                lengths[i][j] = -1; // we were here
                indices[i][j] = 0;
                int length = 1;
                int cycle = 0;
                int cycX = -1, cycY = -1;

                while (true) {
                    auto [xc, yc] = st.top();
                    if (a[xc][yc] == 'U') {
                        xc--;
                    } else if (a[xc][yc] == 'D') {
                        xc++;
                    } else if (a[xc][yc] == 'L') {
                        yc--;
                    } else {
                        yc++;
                    }

                    if (xc < 0 || xc >= n || yc < 0 || yc >= m) {
                        break;
                    } else if (lengths[xc][yc] < 0) {
                        cycle -= indices[xc][yc] - 1;
                        length = cycle + 1;
                        cycX = xc;
                        cycY = yc;
                        break;
                    } else if (lengths[xc][yc] > 0) {
                        length = lengths[xc][yc] + 1;
                        break;
                    } else {
                        lengths[xc][yc] = -1;
                        indices[xc][yc] = ++cycle;
                        st.push({xc, yc});
                    }
                }

                bool isCycle = cycX != -1;
                int len = isCycle ? cycle : length;

                while (!st.empty()) {
                    auto [xy, yz] = st.top();
                    lengths[xy][yz] = len;
                    if (isCycle) {
                        if (xy == cycX && yz == cycY) {
                            isCycle = false;
                            len = length;
                        }
                    } else {
                        ++len;
                    }
                    st.pop();
                }

                if (max_length < lengths[i][j]) {
                    max_length = lengths[i][j];
                    x = i + 1;
                    y = j + 1;
                }
            }
        }
    }

    out << x << " " << y << " " << max_length << endl;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int count = 0;
    cin >> count;

    while (count-- > 0) {
        solve(cin, cout);
    }

    return 0;
}

