const long mod = 998244353;

long fact[4001];
long invFact[4001];

long binPow(long a, long b) {
    long res = 1;
    while (b > 0) {
        a = a % mod;
        if ((b & 1) == 1) {
            res = (res * a) % mod;
        }
        b >>= 1;
        a = (a * a) % mod;
    }
    return res;
}

long modInverse(long a) {
    return binPow(a, mod - 2);
}

long mul(long a, long b) {
    return (a * b) % mod;
}

long nCr(int n, int r) {
    if (r > n)
        return 0;
    long res = mul(fact[n], invFact[r]);
    res = mul(res, invFact[n - r]);
    return res;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;
    std::vector<std::string> ls(n);
    bool full = false;
    int black = 0, white = 0;
    for (int i = 0; i < n; ++i) {
        std::cin >> ls[i];
        if (ls[i][0] == 'W')
            white++;
        if (ls[i][0] == 'B')
            black++;
        if (ls[i][1] == 'W')
            white++;
        if (ls[i][1] == 'B')
            black++;
        if (ls[i][0] != '?' && ls[i][0] == ls[i][1]) {
            full = true;
        }
    }
    if (black > n || white > n) {
        std::cout << 0 << '\n';
        return 0;
    }

    fact[0] = 1;
    invFact[0] = 1;
    for (int i = 1; i <= 2 * n; ++i) {
        fact[i] = mul(fact[i - 1], i);
        invFact[i] = modInverse(fact[i]);
    }
    int empty = 2 * n - black - white;
    long ans = nCr(empty, n - black);
    if (full) {
        std::cout << ans << '\n';
        return 0;
    }
    long invalid = 1;
    bool WB = true, BW = true;
    for (int i = 0; i < n; ++i) {
        if (ls[i][0] == '?' && ls[i][1] == '?') {
            invalid = mul(invalid, 2);
        }
        if (ls[i][0] == 'B' || ls[i][1] == 'W') {
            WB = false;
        }
        if (ls[i][0] == 'W' || ls[i][1] == 'B') {
            BW = false;
        }
    }
    if (WB)
        invalid--;
    if (BW)
        invalid--;
    ans = ans - invalid;
    std::cout << ans << '\n';

    return 0;
}

