func isPrime(_ n: Int) -> Bool {
    if n <= 1 { return false }
    if n <= 3 { return true }
    if n % 2 == 0 || n % 3 == 0 { return false }
    for i in stride(from: 5, through: Int(Double(n).squareRoot()), by: 6) {
