class Main {
    let out = OutputStream(toFileAtPath: "/dev/stdout")!
    let inStream = InputStream(fileAtPath: "/dev/stdin")!

    func next() throws -> String {
        var buffer = [UInt8](repeating: 0, count: 1)
        try inStream.read(into: &buffer)
        return String(bytes: buffer, encoding: .utf8)!
    }

    func ni() throws -> Int {
        return Int(try next())!
    }

    func nl() throws -> Int64 {
        return Int64(try next())!
    }

    func na(_ n: Int) throws -> [Int] {
        var result = [Int]()
        for _ in 0..<n {
            result.append(try ni())
        }
        return result
    }

    let mod = 998244353

    func solve() throws {
        try inStream.open()
        defer { out.close() }

        var tc = ni()
        while tc > 0 {
            tc -= 1

            let n = ni()
            let A = try na(n)

            var D = Array(repeating: [Int64](repeating: 0, count: 3), count: n + 1)

            for i in stride(from: n - 1, through: 0, by: -1) {
                let u = A[i]

                var zero = 1 + D[u][0]
                if u + 1 <= n { zero += D[u + 1][0] }
                if u + 2 <= n { zero += D[u + 2][1] }

                var one = 1 + D[u][1]
                if u > 1 { one += D[u - 2][2] }

                var two = 1 + D[u][2]
                if u + 2 <= n { two += D[u + 2][1] }

                D[u][0] = (D[u][0] + zero) % mod
                D[u][1] = (D[u][1] + one) % mod
                D[u][2] = (D[u][2] + two) % mod
            }

            let ans = (D[0][0] + D[1][1]) % mod
            out.write("\(ans)\n".data(using: .utf8)!, maxLength: "\(ans)\n".count)
        }
    }

    func gcd(_ a: Int, _ b: Int) -> Int {
        return (b == 0) ? a : gcd(b, a % b)
    }

    func gcd(_ a: Int64, _ b: Int64) -> Int64 {
        return (b == 0) ? a : gcd(b, a % b)
    }

    func mp(_ a: Int64, _ p: Int64) -> Int64 {
        var r = 1
        var p = p
        var a = a

        while p > 0 {
            if (p & 1) == 1 {
                r = (r * a) % mod
            }
            p >>= 1
            a = (a * a) % mod
        }

        return r
    }
}

