func solve(_ io: FastIOAdapter) {
    let n = io.nextInt()
    let m = io.nextInt()
    var a = [[Character]](repeating: [Character](), count: n)
    for i in 0..<n {
        a[i] = Array(io.next())
    }
    var lengths = [[Int]](repeating: [Int](repeating: 0, count: m), count: n)
    var indices = [[Int]](repeating: [Int](repeating: 0, count: m), count: n)
    var x = 0, y = 0
    var max = 0
    for i in 0..<n {
        for j in 0..<m {
            if lengths[i][j] == 0 { // we did not check this
                var stack = [(Int, Int)]()
                stack.append((i, j))
                lengths[i][j] = -1 // we were here
                indices[i][j] = 0
                var length = 1
                var cycle = 0
                var cycX = -1, cycY = -1
                while true {
                    let (xc, yc) = stack.last!
                    var nextX = xc, nextY = yc
                    if a[xc][yc] == "U" {
                        nextX -= 1
                    } else if a[xc][yc] == "D" {
                        nextX += 1
                    } else if a[xc][yc] == "L" {
                        nextY -= 1
                    } else {
                        nextY += 1
                    }
                    if nextX < 0 || nextX >= n || nextY < 0 || nextY >= m {
                        break
                    } else if lengths[nextX][nextY] < 0 {
                        cycle -= indices[nextX][nextY] - 1
                        length = cycle + 1
                        cycX = nextX
                        cycY = nextY
                        break
                    } else if lengths[nextX][nextY] > 0 {
                        length = lengths[nextX][nextY] + 1
                        break
                    } else {
                        lengths[nextX][nextY] = -1
                        indices[nextX][nextY] += cycle
                        stack.append((nextX, nextY))
                    }
                }
                let isCycle = cycX != -1
                var len = isCycle ? cycle : length
                while !stack.isEmpty {
                    let (xc, yc) = stack.removeLast()
                    lengths[xc][yc] = len
                    if isCycle {
                        if xc == cycX && yc == cycY {
                            isCycle = false
                            len = length
                        }
                    } else {
                        len += 1
                    }
                }
                if max < lengths[i][j] {
                    max = lengths[i][j]
                    x = i + 1
                    y = j + 1
                }
            }
        }
    }
    io.print("\(x) \(y) \(max)\n")
}

