                        var mn = Int.max
                        var tempMod = mod
                        while tempMod <= ar[l] && tempMod <= 9 {
                            if mod3[tempMod][0] == 1 {
                                mn = min((ar[l] - tempMod) / 3, mn)
                            }
                            tempMod += 3
                        }
                        mx = max(mx, mn)
                    }
                    if mx == Int.max { continue }
                    ans = min(ans, mx + j + k)
                }
            }
            print(ans)
        }
    }
}

