import Foundation

enum Constants {
    static let mod = 998244353
}

class D {
    private static var fact: [Int64] = Array(repeating: 0, count: 401)
    private static var invFact: [Int64] = Array(repeating: 0, count: 401)

    // Fermat's Little Theorem:
    // (a^p - a) % p = 0
    // => a^p % p - a % p = 0
    // => a^p % p = a % p
    // => a^(p - 1) % p = (a * a^-1) % p
    // => a^(p - 1) % p = 1 % p
    // => a^(p - 2) % p = a^-1 % p

    private static func binPow(_ a: Int64, _ b: Int64) -> Int64 {
        var res = Int64(1)
        var a = a % Constants.mod
        var b = b
        while b > 0 {
            if (b & 1) == 1 {
                res = (res * a) % Constants.mod
            }
            b >>= 1
            a = (a * a) % Constants.mod
        }
        return res
    }

    private static func modInverse(_ a: Int64) -> Int64 {
        return binPow(a, Constants.mod - 2)
    }

    private static func mul(_ a: Int64, _ b: Int64) -> Int64 {
        return (a * b) % Constants.mod
    }

    private static func nCr(_ n: Int, _ r: Int) -> Int64 {
        let res = mul(fact[n], invFact[r])
        return mul(res, invFact[n - r])
    }

    public static func main() {
        let n = Int(readLine()!)!
        var ls = [String]()
        var full = false
        var black = 0, white = 0
        for _ in 0..<n {
            let line = readLine()!
            ls.append(line)
            if line.first == "W" {
                white += 1
            }
            if line.first == "B" {
                black += 1
            }
            if line.count > 1 && (line[line.index(line.startIndex, offsetBy: 1)] == "W" || line[line.index(line.startIndex, offsetBy: 1)] == "B") {
                full = true
            }
        }
        if black > n || white > n {
            print(0)
            return
        }

        fact[0] = 1
        invFact[0] = 1
        for i in 1...2 * n {
            fact[i] = mul(fact[i - 1], Int64(i))
            invFact[i] = modInverse(Int64(i))
        }
        let empty = 2 * n - black - white
        var ans = nCr(empty, n - black)
        if full {
            print(ans)
            return
        }
        var invalid = Int64(1)
        var WB = true, BW = true
        for line in ls {
            if line.count == 2 && (line.first! == "?" || line.last! == "?") {
                invalid *= 2
            } 
            if line.first! == "B" || line.last! == "W" {
                WB = false
            }
            if line.first! == "W" || line.last! == "B" {
                BW = false
            }
        }
        if WB {
            invalid -= 1
        }
        if BW {
            invalid -= 1
        }
        ans -= invalid
        print(ans)
    }
}

