class StringTokenizer {
    private let reader: StreamReader
    private var tokens: [String]
    private var index: Int

    init(reader: StreamReader) {
        self.reader = reader
        self.tokens = []
        self.index = 0
        readTokens()
    }

    func nextToken() -> String {
        if index < tokens.count {
            let token = tokens[index]
            index += 1
            return token
        } else {
            readTokens()
            return nextToken()
        }
    }

    private func readTokens() {
        guard let line = reader.readLine(), !line.isEmpty else { return }
        tokens = line.split(separator: " ").map(String.init)
        index = 0
    }
}

