        var result = ""
        while index < buffer.count {
            if buffer[index] == 10 { // newline character
                index += 1
                break
            } else if buffer[index] != 32 && buffer[index] != 9 { // not space or tab
                if let char = Character(UnicodeScalar(buffer[index])) {
                    result.append(char)
                }
            }
            index += 1
        }
        return result
    }

